@checkOnScreen:
    lda     oamBuffer+128,y         ; $83FD  off the screen?
    cmp     #$F8                    ; $8400
    bcs     @remove                 ; $8402
    lda     oamBuffer+131,y         ; $8404
    cmp     #$F8                    ; $8407
