    sec                             ; $8654
    sbc     #$0B                    ; $8655
    sta     overworldTargetY        ; $8657
    jsr     Overworld_SetMapPosition ; $8659
    lda     overworldMapRow         ; $865C
    lsr     a                       ; $865E
    bcc     @moveLeft               ; $865F
    dec     overworldTargetY        ; $8661
    lda     overworldTargetY        ; $8663
    jsr     Overworld_SetMapPosition ; $8665

@moveLeft:
