; ---------------------------------------------------------------------------
; Overworld_CanWalk
;
; Check the terrain under Link on the overworld (Overworld_UpdateTerrain).
; Terrain $0B and above blocks him (his velocity is cleared), except $0D,
; which he can cross with the boots.
;
; Out:     carry clear if he can walk there
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_CanWalk:
    jsr     Overworld_UpdateTerrain ; $870F  the terrain under Link
    cmp     #$0D                    ; $8712  water the boots walk on ($0D)?
    bne     @checkBlock             ; $8714
    ldy     itemOwned+ITEM_BOOTS    ; $8716  the boots walk on it
    bne     @walkable               ; $8719

@checkBlock:
    cmp     #$0B                    ; $871B  $0B and up block
    bcs     @blocked                ; $871D

@walkable:
    clc                             ; $871F
    rts                             ; $8720

@blocked:
    lda     #$00                    ; $8721  blocked:
    sta     objXVelocity            ; $8723  no step
    rts                             ; $8725

; ---------------------------------------------------------------------------
; Overworld_DrawLink
;
; Draw Link on the overworld at X $84, Y $6D (sprites 0 and 1), by
; overworldDirection, flipping his walk every 8 frames; and a column of 15
; sprites (2-16, tile $FF) down the screen's right edge, which hides the
; map column being drawn (seen as a black 8-pixel strip).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_DrawLink:
    lda     #$84                    ; $8726  at X $84

; ---------------------------------------------------------------------------
; Overworld_DrawLinkAtX
;
; Overworld_DrawLink at X = a (Link on the raft).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_DrawLinkAtX:
    sta     oamBuffer+3             ; $8728  two sprites, 8 apart,
    clc                             ; $872B
    adc     #$08                    ; $872C
    sta     oamBuffer+7             ; $872E
    lda     #$6D                    ; $8731  at Y $6D
    sta     oamBuffer               ; $8733
    sta     oamBuffer+4             ; $8736
    lda     #$F5                    ; $8739  the right one: tile $F5,
    sta     oamBuffer+5             ; $873B
    lda     #$40                    ; $873E  flipped
    sta     oamBuffer+6             ; $8740
    lda     overworldDirection      ; $8743  left or right?
    cmp     #$04                    ; $8746
    bcs     @upDown                 ; $8748
    lsr     a                       ; $874A  right: flip the left one
    lda     #$00                    ; $874B
    ror     a                       ; $874D
    lsr     a                       ; $874E
    sta     oamBuffer+2             ; $874F
    ldx     #$77                    ; $8752  tile $77,
    lda     overworldMoveFrames     ; $8754  walking:
    beq     @setTile                ; $8756
    and     #$08                    ; $8758  every other 8 frames
    bne     @setTile                ; $875A
    dex                             ; $875C  tile $75
    dex                             ; $875D

@setTile:
    stx     oamBuffer+1             ; $875E
    bpl     @edgeColumn             ; $8761  (always)

@upDown:
    ldx     #$7B                    ; $8763  down: tile $7B,
    cmp     #$04                    ; $8765
    beq     @setUpDownTile          ; $8767
    dex                             ; $8769
    dex                             ; $876A

@setUpDownTile:
    stx     oamBuffer+1             ; $876B  up: $79
    ldx     #$40                    ; $876E  flipped,
    lda     overworldMoveFrames     ; $8770  walking:
    beq     @setFlip                ; $8772
    and     #$08                    ; $8774  every other 8 frames
    bne     @setFlip                ; $8776
    tax                             ; $8778  unflipped

@setFlip:
    stx     oamBuffer+2             ; $8779

@edgeColumn:
    ldx     #$0E                    ; $877C  15 sprites (2-16) down the right edge:
    ldy     #$00                    ; $877E
    sty     temp0                   ; $8780

@loop:
    lda     temp0                   ; $8782  Y 0, 16, 32, ...
    sta     oamBuffer+8,y           ; $8784
    clc                             ; $8787
    adc     #$10                    ; $8788
    sta     temp0                   ; $878A
    lda     #$FF                    ; $878C  tile $FF
    sta     oamBuffer+9,y           ; $878E
    lda     #$F8                    ; $8791  X $F8
    sta     oamBuffer+11,y          ; $8793
    lda     #$01                    ; $8796  palette 1, in front: hides the column being drawn
    sta     oamBuffer+10,y          ; $8798
    iny                             ; $879B
    iny                             ; $879C
    iny                             ; $879D
    iny                             ; $879E
    dex                             ; $879F
    bpl     @loop                   ; $87A0
    rts                             ; $87A2

; Tiles of each overworld terrain (16), 4 per terrain: top left, bottom left,
; top right, bottom right.
OverworldTileMetatiles:
    .byte   $5C, $5D, $5E, $5F, $F4, $F4, $F4, $F4, $60, $61, $62, $63, $5A, $5A, $5B, $5B; $87A3
    .byte   $6C, $6C, $6C, $6C, $6D, $6D, $6D, $6D, $68, $69, $6A, $6B, $6F, $6F, $6F, $6F; $87B3
    .byte   $70, $71, $FE, $FE, $FE, $FE, $FE, $FE, $6E, $6E, $6E, $6E, $64, $65, $66, $67; $87C3
    .byte   $6E, $6E, $6E, $6E, $6E, $6E, $6E, $6E, $56, $57, $58, $59, $40, $41, $42, $43; $87D3

OverworldTerrainPalettes:
    .byte   $02, $01, $02, $01, $03, $00, $00, $00, $01, $01, $01, $01, $03, $03, $01, $01; $87E3

; ---------------------------------------------------------------------------
; Mode_IndexOverworldMap
;
; gameMode 3: decode the overworld map's 75 rows (Overworld_DecodeRow),
; keeping a pointer to each in sramAreaTiles, then draw the screen around
; Link row by row, writing each row to the PPU at once (rendering is off).
; Then set up the overworld objects and terrain, start the music and the
; entry sound, and go on to gameMode 4 (or $18).
;
; All of this runs inside one game NMI with further NMIs disabled: about
; 530,000 cycles, some 18 frames (measured on the 100% movie).  The music
; keeps going because each drawn row calls Sound_UpdateSometimes.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Mode_IndexOverworldMap:
    lda     #$00                    ; $87F3  the compressed map, sramOverworldMap ($7C00)
    sta     temp14                  ; $87F5
    lda     #$7C                    ; $87F7
    sta     temp15                  ; $87F9
    ldy     #$00                    ; $87FB  row 0's pointer first
    sty     temp0                   ; $87FD
    beq     @savePtr                ; $87FF

@loop:
    ldx     #$00                    ; $8801  decode a row (to find its end):
    stx     temp3                   ; $8803
    ldy     #$00                    ; $8805
    jsr     Overworld_DecodeRow     ; $8807

@savePtr:
    ldx     temp0                   ; $880A  the next row's pointer:
    tya                             ; $880C
    clc                             ; $880D  its start + the bytes read
    adc     temp14                  ; $880E
    sta     temp14                  ; $8810
    sta     sramAreaTiles,x         ; $8812  into sramAreaTiles
    lda     temp15                  ; $8815
    adc     #$00                    ; $8817
    sta     temp15                  ; $8819
    sta     sramAreaTiles+1,x       ; $881B
    inx                             ; $881E
    inx                             ; $881F
    stx     temp0                   ; $8820
    txa                             ; $8822  75 rows?
    lsr     a                       ; $8823
    cmp     #$4B                    ; $8824
    bne     @loop                   ; $8826
    lda     #$00                    ; $8828  draw 23 rows around Link:
    sta     overworldDrawStep       ; $882A

@loop2:
    lda     overworldTargetX        ; $882C  one step of the row
    sta     temp0                   ; $882E
    lda     overworldTargetY        ; $8830
    sta     temp1                   ; $8832
    jsr     Overworld_DrawRowStep   ; $8834
    lda     #$02                    ; $8837  write the queued strings now
    sta     temp0                   ; $8839
    lda     #$03                    ; $883B
    sta     temp1                   ; $883D
    jsr     Ppu_WriteStrings        ; $883F  (rendering is off)
    lda     #$00                    ; $8842  empty the buffer
    sta     ppuBuffer0Len           ; $8844
    lda     #$FF                    ; $8847
    sta     ppuBuffer0              ; $8849
    lda     overworldDrawStep       ; $884C  all 6 steps?
    cmp     #$06                    ; $884E
    bne     @loop2                  ; $8850
    inc     overworldTargetY        ; $8852  the next row down,
    lda     overworldTargetY        ; $8854
    jsr     Math_DivMod15           ; $8856  its screen and row
    sta     temp0                   ; $8859
    tya                             ; $885B
    asl     a                       ; $885C
    asl     a                       ; $885D
    asl     a                       ; $885E
    asl     a                       ; $885F
    ora     temp0                   ; $8860
    sta     overworldMapRow         ; $8862
    jsr     Sound_UpdateSometimes   ; $8864  keep the music going
    ldx     #$00                    ; $8867  from step 0
    stx     overworldDrawStep       ; $8869
    dec     objXVelocity+1          ; $886B  all 23?
    bne     @loop2                  ; $886D
    ldy     #$07                    ; $886F  no encounters

@loop3:
    stx     objState+2,y            ; $8871
    dey                             ; $8873
    bpl     @loop3                  ; $8874
    inx                             ; $8876  walking frames 1
    stx     overworldWalkFrames     ; $8877
    lda     #$08                    ; $8879  encounters after 8 x 20 frames
    sta     timerSlow+8             ; $887B
    jsr     Overworld_UpdateTerrain ; $887E  the terrain under Link
    lda     raftArrived             ; $8881  after a raft ride or at the special spot:
    ora     atSpecialSpot           ; $8884
    bne     @nextMode               ; $8887  no music or sound
    lda     currentRegion           ; $8889  North Castle (region 0, location 0):
    ora     areaLocation            ; $888C
    beq     @sound                  ; $888F  keep its music
    lda     #$02                    ; $8891  the overworld theme
    sta     musicRequest            ; $8893

@sound:
    ldx     #$00                    ; $8895  sound on,
    stx     soundMute               ; $8897
    lda     overworldEntrySfx       ; $8899  the leaving sound
    sta     sfxRequest+2            ; $889C

@nextMode:
    lda     #$04                    ; $889E  gameMode 4: unblank
    ldy     raftArrived             ; $88A0  after a raft ride:
    beq     @setMode                ; $88A3
    ldx     #$00                    ; $88A5  (once)
    stx     raftArrived             ; $88A7
    stx     renderingOff            ; $88AA  rendering on at once
    lda     #$18                    ; $88AD  gameMode $18: ride in

@setMode:
    sta     gameMode                ; $88AF

; ---------------------------------------------------------------------------
; Mode_IndexOverworldMapDone
;
; Return (shared tail of Mode_IndexOverworldMap).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Mode_IndexOverworldMapDone:
    rts                             ; $88B2

; ---------------------------------------------------------------------------
; Overworld_DrawRowStep
;
; While Link moves up or down on the overworld, run the current step
; (overworldDrawStep) of drawing the map row scrolling into view: decode
; the row (Overworld_DecodeRowAt), queue its two tile rows
; (Overworld_QueueRowTiles), move to the next row (Overworld_NextRow),
; shift the decoded rows (Overworld_ScrollRowBuffer), queue the row's
; attributes (Overworld_QueueRowAttrs), then idle.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_DrawRowStep:
    lda     a:overworldDrawStep     ; $88B3  the step
    jsr     JumpTable               ; $88B6
; (inline jump table)
    .word   Overworld_DecodeRowAt   ; $88B9
    .word   Overworld_QueueRowTiles ; $88BB
    .word   Overworld_QueueRowTiles ; $88BD
    .word   Overworld_NextRow       ; $88BF
    .word   Overworld_ScrollRowBuffer ; $88C1
    .word   Overworld_QueueRowAttrs ; $88C3
    .word   Overworld_Idle          ; $88C5

; ---------------------------------------------------------------------------
; Overworld_DrawColumnStep
;
; While Link moves left or right on the overworld (and fewer than 14
; frames of the move are left), run the current step (overworldDrawStep)
; of drawing the map column scrolling into view: decode the column
; (Overworld_DecodeColumn), queue its tiles in six parts
; (Overworld_QueueColumnTiles), decode the neighboring column
; (Overworld_DecodeNextColumns), queue the attributes in two parts, then
; idle.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_DrawColumnStep:
    lda     overworldMoveFrames     ; $88C7  the move's first 2 frames:
    cmp     #$0E                    ; $88C9
    bcs     Mode_IndexOverworldMapDone ; $88CB  nothing
    lda     overworldDrawStep       ; $88CD  the step
    jsr     JumpTable               ; $88CF
; (inline jump table)
    .word   Overworld_DecodeColumn  ; $88D2
    .word   Overworld_QueueColumnTiles ; $88D4
    .word   Overworld_QueueColumnTiles ; $88D6
    .word   Overworld_QueueColumnTiles ; $88D8
    .word   Overworld_QueueColumnTiles ; $88DA
    .word   Overworld_QueueColumnTiles ; $88DC
    .word   Overworld_QueueColumnTiles ; $88DE
    .word   Overworld_DecodeNextColumns ; $88E0
    .word   Overworld_QueueColumnAttrsTop ; $88E2
    .word   Overworld_QueueColumnAttrsBottom ; $88E4
    .word   Overworld_Idle          ; $88E6

; ---------------------------------------------------------------------------
; Overworld_DecodeColumn
;
; Decode the 24 map squares of the overworld column at overworldTargetX
; (from rows overworldTargetY - $1E on) into overworldBuffer+$D0, using
; the row index (Overworld_GetRowPtr, Overworld_ReadMapRun); rows outside
; the map are ocean ($0B) or $0C.  Advance overworldDrawStep.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_DecodeColumn:
    lda     overworldDirection      ; $88E8  moving left?
    lsr     a                       ; $88EB
    bcs     @fill                   ; $88EC
    inc     overworldDrawAddrLo     ; $88EE  start at the square's right tile column

@fill:
    ldx     #$17                    ; $88F0  24 squares:
    lda     #$0C                    ; $88F2  off the map: water ($0C),
    ldy     currentRegion           ; $88F4  in regions 0-1,
    cpy     #$02                    ; $88F7
    bcs     @fillLoop               ; $88F9
    ldy     overworldTargetX        ; $88FB  left of column $0C:
    cpy     #$0C                    ; $88FD
    bpl     @fillLoop               ; $88FF
    lda     #$0B                    ; $8901  mountains ($0B)

@fillLoop:
    sta     overworldBuffer+$D0,x   ; $8903
    dex                             ; $8906
    bpl     @fillLoop               ; $8907
    lda     overworldDrawAddrHi     ; $8909  the next tile column's address, the same for now
    sta     overworldNextAddrHi     ; $890B
    lda     overworldDrawAddrLo     ; $890D
    sta     overworldNextAddrLo     ; $890F
    lda     overworldTargetY        ; $8911  from 30 rows above the target row
    sec                             ; $8913
    sbc     #$1E                    ; $8914
    sta     temp10                  ; $8916
    lda     overworldTargetX        ; $8918  off the map's right?
    cmp     #$40                    ; $891A
    bcs     @done                   ; $891C  yes: all filler
    ldx     #$00                    ; $891E  each square:

@loop:
    lda     temp10                  ; $8920  off the map's bottom (or top)?
    cmp     #$4B                    ; $8922
    bcs     @nextSquare             ; $8924
    jsr     Overworld_GetRowPtr     ; $8926  no: its row
    lda     #$FF                    ; $8929  (temp3: the last column read)
    sta     temp3                   ; $892B

@loop2:
    jsr     Overworld_ReadMapRun    ; $892D  runs until one reaches the column
    iny                             ; $8930
    cmp     overworldTargetX        ; $8931
    bcc     @loop2                  ; $8933
    lda     temp2                   ; $8935  its terrain
    sta     overworldBuffer+$D0,x   ; $8937

@nextSquare:
    inc     temp10                  ; $893A  next row
    inx                             ; $893C
    cpx     #$18                    ; $893D
    bne     @loop                   ; $893F

@done:
    inc     overworldDrawStep       ; $8941  next step
    lda     #$00                    ; $8943  from square 0 (linkStanding is reused)
    sta     linkStanding            ; $8945
    rts                             ; $8947

; ---------------------------------------------------------------------------
; Overworld_QueueColumnTiles
;
; Queue one part of the decoded column's tiles (OverworldTileMetatiles by
; terrain) as vertical PPU strings at overworldDrawAddrHi/Lo, splitting
; the column where it wraps from one nametable to the other.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_QueueColumnTiles:
    lda     overworldDrawAddrHi     ; $8948  a vertical string at the draw address
    sta     ppuBuffer0              ; $894A
    sta     temp14                  ; $894D
    lda     overworldDrawAddrLo     ; $894F
    sta     ppuBuffer0+1            ; $8951
    sta     temp15                  ; $8954
    lda     #$00                    ; $8956  its length
    sta     temp6                   ; $8958
    lda     linkStanding            ; $895A  from the square reached
    sta     temp7                   ; $895C

@square:
    ldx     temp7                   ; $895E  each square's terrain:
    lda     overworldBuffer+$D0,x   ; $8960  its 4 tiles
    asl     a                       ; $8963
    asl     a                       ; $8964
    tax                             ; $8965
    lda     overworldDirection      ; $8966  moving right:
    lsr     a                       ; $8969
    beq     @movingRight            ; $896A
    lda     overworldDrawStep       ; $896C  left tiles first (steps 1-3)
    and     #$04                    ; $896E
    bne     @tiles                  ; $8970
    inx                             ; $8972  then right
    inx                             ; $8973
    bne     @tiles                  ; $8974

@movingRight:
    lda     overworldDrawStep       ; $8976  moving left: right tiles first
    and     #$04                    ; $8978
    beq     @tiles                  ; $897A
    inx                             ; $897C
    inx                             ; $897D

@tiles:
    ldy     temp6                   ; $897E  two tiles,
    lda     OverworldTileMetatiles,x ; $8980
    sta     ppuBuffer0+3,y          ; $8983
    inc     temp6                   ; $8986
    inx                             ; $8988
    txa                             ; $8989
    and     #$01                    ; $898A
    bne     @tiles                  ; $898C
    inc     temp7                   ; $898E  next square
    lda     temp7                   ; $8990  all 24?
    cmp     #$18                    ; $8992
    bne     @nextTileRow            ; $8994
    lda     temp6                   ; $8996  yes: end the string
    ora     #$80                    ; $8998
    sta     ppuBuffer0+2            ; $899A
    lda     #$FF                    ; $899D
    sta     ppuBuffer0+4,y          ; $899F
    lda     overworldDrawStep       ; $89A2  the first tile column?
    and     #$04                    ; $89A4
    bne     @bothDone               ; $89A6
    sta     linkStanding            ; $89A8  yes: the second from square 0,
    lda     #$04                    ; $89AA  at step 4
    bne     @setStep                ; $89AC

@bothDone:
    lda     #$07                    ; $89AE  no: done (step 7)

@setStep:
    sta     overworldDrawStep       ; $89B0
    lda     overworldDirection      ; $89B2  the second tile column:
    lsr     a                       ; $89B5
    beq     @rightOfIt              ; $89B6
    dec     overworldNextAddrLo     ; $89B8  left of the first
    jmp     @setNext                ; $89BA

@rightOfIt:
    inc     overworldNextAddrLo     ; $89BD  right of it

@setNext:
    lda     overworldNextAddrHi     ; $89BF
    sta     overworldDrawAddrHi     ; $89C1
    lda     overworldNextAddrLo     ; $89C3
    sta     overworldDrawAddrLo     ; $89C5
    rts                             ; $89C7

@nextTileRow:
    lda     temp15                  ; $89C8  the next tile row's address
    clc                             ; $89CA
    adc     #$40                    ; $89CB
    sta     temp15                  ; $89CD
    lda     temp14                  ; $89CF
    adc     #$00                    ; $89D1
    sta     temp14                  ; $89D3
    and     #$03                    ; $89D5  into the attribute table (row 30)?
    cmp     #$03                    ; $89D7
    bne     @continue               ; $89D9
    lda     temp15                  ; $89DB
    and     #$F0                    ; $89DD
    cmp     #$C0                    ; $89DF
    bcs     @wrap                   ; $89E1

@continue:
    jmp     @square                 ; $89E3  no: next square

@wrap:
    lda     temp6                   ; $89E6  yes: end the string here
    ora     #$80                    ; $89E8
    sta     ppuBuffer0+2            ; $89EA
    lda     #$FF                    ; $89ED
    sta     ppuBuffer0+4,y          ; $89EF
    lda     overworldDrawAddrLo     ; $89F2  and go on at the top
    and     #$1F                    ; $89F4
    sta     overworldDrawAddrLo     ; $89F6
    lda     overworldDrawAddrHi     ; $89F8  of the other nametable
    eor     #$08                    ; $89FA
    and     #$F8                    ; $89FC
    sta     overworldDrawAddrHi     ; $89FE
    lda     temp7                   ; $8A00  from this square
    sta     linkStanding            ; $8A02
    inc     overworldDrawStep       ; $8A04  next step
    rts                             ; $8A06

; ---------------------------------------------------------------------------
; Overworld_UpdateTerrain
;
; Set overworldTerrain to the terrain under Link.  Overworld_GetTerrainAtX
; gets the terrain at X = a, Y = temp1.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_UpdateTerrain:
    lda     overworldY              ; $8A07  Link's square
    sta     temp1                   ; $8A09
    lda     overworldX              ; $8A0B

; ---------------------------------------------------------------------------
; Overworld_GetTerrainAtX
;
; Set overworldTerrain to the terrain at X = a, Y = temp1.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_GetTerrainAtX:
    sta     temp0                   ; $8A0D
    jsr     Overworld_GetTerrain    ; $8A0F
    lda     temp2                   ; $8A12  its terrain
    sta     overworldTerrain        ; $8A14
    rts                             ; $8A17

OverworldRowSteps:
    .byte   $01, $FF                                                        ; $8A18

; ---------------------------------------------------------------------------
; Overworld_NextRow
;
; Move to the next map row in the direction of travel (OverworldRowSteps)
; and decode it, or skip to the attribute step on odd rows.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_NextRow:
    lda     overworldDirection      ; $8A1A  moving down
    and     #$04                    ; $8A1D
    beq     @checkOdd               ; $8A1F
    lda     overworldMapRow         ; $8A21  and not on the nametable's last row (14):
    and     #$0F                    ; $8A23
    cmp     #$0E                    ; $8A25
    beq     @checkOdd               ; $8A27
    lsr     a                       ; $8A29  an even row: decode the next
    bcs     @decode                 ; $8A2A

@attrs:
    lda     #$06                    ; $8A2C  odd: the attributes now (step 6)
    sta     overworldDrawStep       ; $8A2E
    rts                             ; $8A30

@checkOdd:
    lda     overworldMapRow         ; $8A31  moving up, or row 14: odd?
    lsr     a                       ; $8A33
    bcs     @attrs                  ; $8A34  then the attributes

@decode:
    jsr     Overworld_ShiftRowBuffer ; $8A36  decode the next row:
    lda     overworldDirection      ; $8A39  down: +1, up: -1
    and     #$04                    ; $8A3C
    lsr     a                       ; $8A3E
    lsr     a                       ; $8A3F
    tay                             ; $8A40
    lda     overworldTargetY        ; $8A41  (carry clear)
    adc     OverworldRowSteps,y     ; $8A43
    sta     temp1                   ; $8A46
    jmp     Overworld_DecodeRowAt   ; $8A48  into the second row buffer

; ---------------------------------------------------------------------------
; Overworld_ShiftRowBuffer
;
; Copy the second row buffer (overworldBuffer+$70, 96 squares) to the
; first (+$10).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_ShiftRowBuffer:
    ldy     #$5F                    ; $8A4B  the decoded row (+$70, 96 squares) to the first buffer (+$10)

@loop:
    lda     overworldBuffer+$70,y   ; $8A4D
    sta     overworldBuffer+$10,y   ; $8A50
    dey                             ; $8A53
    bpl     @loop                   ; $8A54
    rts                             ; $8A56

; ---------------------------------------------------------------------------
; Overworld_ScrollRowBuffer
;
; Copy the squares past the 16-column window back into it, in both row
; buffers, so that the window's columns follow each other from
; (overworldTargetX + 16) & $F0; then advance overworldDrawStep.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_ScrollRowBuffer:
    lda     overworldTargetX        ; $8A57  the target column within 16
    and     #$0F                    ; $8A59
    beq     @done                   ; $8A5B  aligned: nothing
    tax                             ; $8A5D
    lda     overworldTargetX        ; $8A5E  the columns past the window's 16
    clc                             ; $8A60
    adc     #$10                    ; $8A61
    and     #$F0                    ; $8A63
    tay                             ; $8A65

@loop:
    lda     overworldBuffer+$20,y   ; $8A66  copied back into it
    sta     overworldBuffer+$10,y   ; $8A69
    lda     overworldBuffer+$80,y   ; $8A6C  (both row buffers)
    sta     overworldBuffer+$70,y   ; $8A6F
    iny                             ; $8A72
    dex                             ; $8A73
    bne     @loop                   ; $8A74

@done:
    inc     overworldDrawStep       ; $8A76  next step
    rts                             ; $8A78

; ---------------------------------------------------------------------------
; Overworld_QueueRowAttrs
;
; Queue the eight attribute bytes for the decoded rows, built from the
; terrain palettes (OverworldTerrainPalettes).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_QueueRowAttrs:
    lda     overworldMapRow         ; $8A79  the attribute table of the row's nametable
    and     #$10                    ; $8A7B
    lsr     a                       ; $8A7D
    ora     #$23                    ; $8A7E
    sta     ppuBuffer0              ; $8A80  ($23C0 or $2BC0)
    lda     overworldMapRow         ; $8A83  its attribute row
    and     #$0E                    ; $8A85
    asl     a                       ; $8A87
    asl     a                       ; $8A88
    ora     #$C0                    ; $8A89
    sta     ppuBuffer0+1            ; $8A8B
    lda     #$08                    ; $8A8E  8 bytes
    sta     ppuBuffer0+2            ; $8A90
    lda     overworldTargetX        ; $8A93  the window's 16 squares
    adc     #$10                    ; $8A95
    and     #$F0                    ; $8A97
    tay                             ; $8A99
    ldx     #$00                    ; $8A9A
    stx     temp14                  ; $8A9C

@loop:
    ldx     temp14                  ; $8A9E  each byte:
    lda     #$00                    ; $8AA0  from 0
    sta     ppuBuffer0+3,x          ; $8AA2
    ldx     overworldBuffer+$10,y   ; $8AA5  top left square
    lda     OverworldTerrainPalettes,x ; $8AA8
    jsr     Attr_SetTopLeft         ; $8AAB
    ldx     overworldBuffer+$11,y   ; $8AAE  top right
    lda     OverworldTerrainPalettes,x ; $8AB1
    jsr     Attr_SetTopRight        ; $8AB4
    ldx     overworldBuffer+$70,y   ; $8AB7  bottom left (second row)
    lda     OverworldTerrainPalettes,x ; $8ABA
    jsr     Attr_SetBottomLeft      ; $8ABD
    ldx     overworldBuffer+$71,y   ; $8AC0  bottom right
    lda     OverworldTerrainPalettes,x ; $8AC3
    jsr     Attr_SetBottomRight     ; $8AC6
    lda     overworldDirection      ; $8AC9  moving down
    and     #$04                    ; $8ACC
    beq     @nextByte               ; $8ACE
    lda     overworldMapRow         ; $8AD0  and not row 14:
    and     #$0F                    ; $8AD2
    cmp     #$0E                    ; $8AD4
    beq     @nextByte               ; $8AD6
    lda     #$00                    ; $8AD8
    sta     temp0                   ; $8ADA
    lda     ppuBuffer0+3,x          ; $8ADC  swap its top and bottom halves
    asl     a                       ; $8ADF
    rol     temp0                   ; $8AE0
    asl     a                       ; $8AE2
    rol     temp0                   ; $8AE3
    asl     a                       ; $8AE5
    rol     temp0                   ; $8AE6
    asl     a                       ; $8AE8
    rol     temp0                   ; $8AE9
    ora     temp0                   ; $8AEB
    sta     ppuBuffer0+3,x          ; $8AED

@nextByte:
    iny                             ; $8AF0  the next two squares
    iny                             ; $8AF1
    inc     temp14                  ; $8AF2
    lda     temp14                  ; $8AF4  8 bytes?
    cmp     #$08                    ; $8AF6
    bcc     @loop                   ; $8AF8
    lda     #$FF                    ; $8AFA  end
    sta     ppuBuffer0+11           ; $8AFC
    inc     overworldDrawStep       ; $8AFF  next step
    rts                             ; $8B01

; ---------------------------------------------------------------------------
; Overworld_DecodeNextColumns
;
; Copy the decoded column to overworldBuffer+$E8 and decode the column
; beside it (or 15 columns away, Overworld_DecodeFarColumn), for the
; attribute bytes, which cover two columns.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_DecodeNextColumns:
    lda     overworldTargetX        ; $8B02  the column's pair for the attributes:
    pha                             ; $8B04
    and     #$01                    ; $8B05  even column: the next (+1),
    eor     #$01                    ; $8B07
    tay                             ; $8B09
    iny                             ; $8B0A  odd: the previous
    cpy     overworldDirection      ; $8B0B  the pair inside the window?
    bne     Overworld_DecodeFarColumn ; $8B0E  no: the column now in its nametable place, 16 away
    cpy     #$02                    ; $8B10  even (y = 2): X + 1
    beq     @plusOne                ; $8B12
    dec     overworldTargetX        ; $8B14  odd: X - 1
    dec     overworldTargetX        ; $8B16

@plusOne:
    inc     overworldTargetX        ; $8B18

; ---------------------------------------------------------------------------
; Overworld_DecodeColumnPair
;
; Copy the decoded column to overworldBuffer+$E8, decode the column at
; overworldTargetX, and restore overworldTargetX from the stack.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_DecodeColumnPair:
    ldx     #$17                    ; $8B1A  keep the decoded column

@loop:
    lda     overworldBuffer+$D0,x   ; $8B1C
    sta     overworldBuffer+$E8,x   ; $8B1F
    dex                             ; $8B22
    bpl     @loop                   ; $8B23
    jsr     Overworld_DecodeColumn  ; $8B25  decode the pair
    pla                             ; $8B28
    sta     overworldTargetX        ; $8B29
    rts                             ; $8B2B

OverworldFarColumnSteps:
    .byte   $0F, $F1                                                        ; $8B2C

; ---------------------------------------------------------------------------
; Overworld_DecodeFarColumn
;
; Move overworldTargetX by OverworldFarColumnSteps (+15 or -15) and decode
; the column pair there.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_DecodeFarColumn:
    dey                             ; $8B2E
    lda     overworldTargetX        ; $8B2F  X + 1 - 16 or X - 1 + 16
    clc                             ; $8B31
    adc     OverworldFarColumnSteps,y ; $8B32
    sta     overworldTargetX        ; $8B35
    jmp     Overworld_DecodeColumnPair ; $8B37

; ---------------------------------------------------------------------------
; Overworld_QueueColumnAttrsTop
;
; Queue the attribute bytes for the top part of the column (11 rows).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_QueueColumnAttrsTop:
    lda     #$0B                    ; $8B3A  rows up to 11
    sta     temp11                  ; $8B3C
    ldx     #$00                    ; $8B3E  from ppuBuffer0's start,
    stx     objXVelocity+2          ; $8B40  square 0

; ---------------------------------------------------------------------------
; Overworld_QueueColumnAttrs
;
; Queue attribute bytes for the decoded column pair, one per two rows,
; until temp11 rows are done, then advance overworldDrawStep.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_QueueColumnAttrs:
    jsr     Overworld_QueueAttrAddress ; $8B42  a byte for two rows
    lda     overworldMapRow         ; $8B45  at the nametable's last row (14)?
    and     #$0F                    ; $8B47
    cmp     #$0E                    ; $8B49  (alone in its attribute row)
    beq     @oneRow                 ; $8B4B
    inc     overworldTargetY        ; $8B4D  no: two rows down
    inc     objXVelocity+2          ; $8B4F

@oneRow:
    inc     overworldTargetY        ; $8B51  one row down
    inc     objXVelocity+2          ; $8B53
    lda     overworldTargetY        ; $8B55  its screen and row
    jsr     Math_DivMod15           ; $8B57
    sta     temp0                   ; $8B5A
    tya                             ; $8B5C
    asl     a                       ; $8B5D
    asl     a                       ; $8B5E
    asl     a                       ; $8B5F
    asl     a                       ; $8B60
    ora     temp0                   ; $8B61
    sta     overworldMapRow         ; $8B63
    lda     objXVelocity+2          ; $8B65  the rows done?
    cmp     temp11                  ; $8B67
    bcc     Overworld_QueueColumnAttrs ; $8B69
    inc     overworldDrawStep       ; $8B6B  next step
    rts                             ; $8B6D

; ---------------------------------------------------------------------------
; Overworld_QueueColumnAttrsBottom
;
; Queue the attribute bytes for the rest of the column (to row 24).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_QueueColumnAttrsBottom:
    lda     #$18                    ; $8B6E  rows up to 24
    sta     temp11                  ; $8B70
    ldx     #$00                    ; $8B72  from ppuBuffer0's start
    beq     Overworld_QueueColumnAttrs ; $8B74

; ---------------------------------------------------------------------------
; Overworld_QueueAttrAddress
;
; Queue an attribute string at ppuBuffer0,x for the map row and column
; being drawn (overworldMapRow, overworldTargetX), with its byte from
; Overworld_QueueAttrByte; x moves past it.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_QueueAttrAddress:
    stx     temp14                  ; $8B76  the string's place
    lda     overworldMapRow         ; $8B78  the attribute table
    and     #$10                    ; $8B7A
    lsr     a                       ; $8B7C
    ora     #$23                    ; $8B7D
    sta     ppuBuffer0,x            ; $8B7F
    lda     overworldMapRow         ; $8B82  attribute row
    and     #$0E                    ; $8B84
    asl     a                       ; $8B86
    asl     a                       ; $8B87
    ora     #$C0                    ; $8B88
    sta     temp0                   ; $8B8A
    lda     overworldTargetX        ; $8B8C  attribute column: X / 2
    lsr     a                       ; $8B8E
    and     #$07                    ; $8B8F
    ora     temp0                   ; $8B91
    sta     ppuBuffer0+1,x          ; $8B93
    lda     #$01                    ; $8B96  one byte
    sta     ppuBuffer0+2,x          ; $8B98
    jsr     Overworld_QueueAttrByte ; $8B9B
    lda     #$FF                    ; $8B9E  end
    sta     ppuBuffer0+4,x          ; $8BA0
    inx                             ; $8BA3  past the string
    inx                             ; $8BA4
    inx                             ; $8BA5
    inx                             ; $8BA6
    rts                             ; $8BA7

; ---------------------------------------------------------------------------
; Overworld_QueueAttrByte
;
; Build an attribute byte from the palettes (OverworldTerrainPalettes) of
; the four terrains it covers, and put it in ppuBuffer0.  Attr_SetBottomRight
; .. Attr_SetTopLeft shift a 2-bit palette into place and OR it in.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_QueueAttrByte:
    lda     #$00                    ; $8BA8  from 0
    sta     ppuBuffer0+3,x          ; $8BAA
    ldy     a:objXVelocity+2        ; $8BAD  the square
    ldx     overworldBuffer+$D0,y   ; $8BB0  the pair's top square (decoded last),
    lda     OverworldTerrainPalettes,x ; $8BB3
    jsr     Attr_SetTopLeft         ; $8BB6
    ldx     overworldBuffer+$E8,y   ; $8BB9  the column's
    lda     OverworldTerrainPalettes,x ; $8BBC
    jsr     Attr_SetTopRight        ; $8BBF
    iny                             ; $8BC2  the row below:
    ldx     overworldBuffer+$D0,y   ; $8BC3
    lda     OverworldTerrainPalettes,x ; $8BC6
    jsr     Attr_SetBottomLeft      ; $8BC9
    ldx     overworldBuffer+$E8,y   ; $8BCC  the column's
    lda     OverworldTerrainPalettes,x ; $8BCF
    jsr     Attr_SetBottomRight     ; $8BD2
    lda     overworldTargetX        ; $8BD5  an even column (its pair on the right)?
    lsr     a                       ; $8BD7
    bcs     @done                   ; $8BD8  no: the pair is on the left, as built
    lda     ppuBuffer0+3,x          ; $8BDA  yes: swap left and right
    pha                             ; $8BDD
    lsr     a                       ; $8BDE
    lsr     a                       ; $8BDF
    and     #$33                    ; $8BE0
    sta     temp0                   ; $8BE2
    pla                             ; $8BE4
    asl     a                       ; $8BE5
    asl     a                       ; $8BE6
    and     #$CC                    ; $8BE7
    ora     temp0                   ; $8BE9
    sta     ppuBuffer0+3,x          ; $8BEB

@done:
    rts                             ; $8BEE

; ---------------------------------------------------------------------------
; Attr_SetBottomRight
;
; OR palette a into the attribute byte at ppuBuffer0+3,temp14, in the
; quadrant given by the entry point: Attr_SetBottomRight shifts it left by
; 6 (bits 7-6), Attr_SetBottomLeft by 4, Attr_SetTopRight by 2, and
; Attr_SetTopLeft not at all (bits 1-0).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Attr_SetBottomRight:
    asl     a                       ; $8BEF
    asl     a                       ; $8BF0

Attr_SetBottomLeft:
    asl     a                       ; $8BF1
    asl     a                       ; $8BF2

Attr_SetTopRight:
    asl     a                       ; $8BF3
    asl     a                       ; $8BF4

Attr_SetTopLeft:
    ldx     temp14                  ; $8BF5  the byte being built
    ora     ppuBuffer0+3,x          ; $8BF7
    sta     ppuBuffer0+3,x          ; $8BFA
    rts                             ; $8BFD

; ---------------------------------------------------------------------------
; Overworld_DecodeRowAt
;
; Decode the overworld map row at Y = temp1 (if inside the map) into
; overworldBuffer+$80, from X = temp0 + $10, after filling the row with
; ocean.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_DecodeRowAt:
    ldx     #$3E                    ; $8BFE  off the map: water ($0C) at columns 11-73,
    lda     #$0C                    ; $8C00

@loop:
    sta     overworldBuffer+$8B,x   ; $8C02
    dex                             ; $8C05
    bpl     @loop                   ; $8C06
    ldx     #$14                    ; $8C08  columns -9 to 11
    ldy     currentRegion           ; $8C0A  in regions 0-1:
    cpy     #$02                    ; $8C0D
    bcs     @fillLeft               ; $8C0F
    lda     #$0B                    ; $8C11  mountains ($0B)

@fillLeft:
    sta     overworldBuffer+$77,x   ; $8C13  (the row buffer +$80 is column 0)
    dex                             ; $8C16
    bpl     @fillLeft               ; $8C17
    ldx     #$00                    ; $8C19  from column 0
    stx     temp3                   ; $8C1B
    lda     temp0                   ; $8C1D
    clc                             ; $8C1F
    adc     #$10                    ; $8C20
    sta     temp0                   ; $8C22
    lda     temp1                   ; $8C24  map row = Y - 30:
    sec                             ; $8C26
    sbc     #$1E                    ; $8C27
    cmp     #$4B                    ; $8C29  off the map?
    bcs     Overworld_NextDrawStep  ; $8C2B  yes: filler only
    jsr     Overworld_GetRowPtr     ; $8C2D  its pointer

; ---------------------------------------------------------------------------
; Overworld_DecodeRow
;
; Decode one row of the compressed overworld map (Overworld_ReadMapRun)
; into overworldBuffer.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_DecodeRow:
    jsr     Overworld_ReadMapRun    ; $8C30  the next run;
    cmp     #$41                    ; $8C33  past column 64?
    bpl     Overworld_NextDrawStep  ; $8C35  yes: done
    lda     temp2                   ; $8C37  its terrain

@loop:
    sta     overworldBuffer+$80,x   ; $8C39  over its length
    inx                             ; $8C3C
    cpx     temp3                   ; $8C3D
    bne     @loop                   ; $8C3F
    iny                             ; $8C41  next byte
    jmp     Overworld_DecodeRow     ; $8C42

; ---------------------------------------------------------------------------
; Overworld_NextDrawStep
;
; Advance overworldDrawStep.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_NextDrawStep:
    inc     overworldDrawStep       ; $8C45
    rts                             ; $8C47

; ---------------------------------------------------------------------------
; Overworld_GetRowPtr
;
; Point temp14 at row a of the compressed overworld map, from the row
; index built in sramAreaTiles by Mode_IndexOverworldMap.
;
; Out:     temp14-temp15 = row pointer, y = 0
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_GetRowPtr:
    asl     a                       ; $8C48  2 bytes per row
    tay                             ; $8C49
    lda     sramAreaTiles,y         ; $8C4A
    sta     temp14                  ; $8C4D
    lda     sramAreaTiles+1,y       ; $8C4F
    sta     temp15                  ; $8C52
    ldy     #$00                    ; $8C54
    rts                             ; $8C56

; ---------------------------------------------------------------------------
; Overworld_QueueRowTiles
;
; Queue one tile row of the decoded map row (OverworldTileMetatiles) at
; overworldDrawAddrHi/Lo, 32 tiles.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Overworld_QueueRowTiles:
    lda     overworldDrawAddrHi     ; $8C57  the draw address,
    sta     ppuBuffer0              ; $8C59
    lda     overworldDrawAddrLo     ; $8C5C  from the row's first tile
    and     #$E0                    ; $8C5E
    sta     ppuBuffer0+1            ; $8C60
    lda     #$20                    ; $8C63  32 tiles
    sta     ppuBuffer0+2            ; $8C65
    lda     #$00                    ; $8C68
    sta     temp6                   ; $8C6A
    lda     temp0                   ; $8C6C  the window's 16 squares
    clc                             ; $8C6E
    adc     #$10                    ; $8C6F
    and     #$F0                    ; $8C71
    sta     temp0                   ; $8C73
    jsr     Overworld_ScrollRowBuffer ; $8C75  made contiguous (also steps the draw step: 2, then 3)

@square:
    ldy     temp0                   ; $8C78  each square:
    cpy     #$60                    ; $8C7A  past the buffer?
    bcc     @terrain                ; $8C7C
; (code below not executed in the test movies)
    lda     #$0C                    ; $8C7E  water ($0C)
    jmp     @tiles                  ; $8C80
; (end of code not executed in the test movies)

@terrain:
    lda     overworldBuffer+$70,y   ; $8C83  its terrain

@tiles:
    asl     a                       ; $8C86  its tiles
    asl     a                       ; $8C87
    tax                             ; $8C88
    ldy     temp6                   ; $8C89
    lda     #$01                    ; $8C8B  two tiles
    sta     temp8                   ; $8C8D
    lda     a:overworldDrawStep     ; $8C8F  the first call (step 2):
    cmp     #$02                    ; $8C92
    beq     @tileLoop               ; $8C94  top tiles (0, 2)
    inx                             ; $8C96  then bottom (1, 3)

@tileLoop:
    lda     OverworldTileMetatiles,x ; $8C97
    sta     ppuBuffer0+3,y          ; $8C9A
    iny                             ; $8C9D
    inx                             ; $8C9E
    inx                             ; $8C9F
    dec     temp8                   ; $8CA0
    bpl     @tileLoop               ; $8CA2
    sty     temp6                   ; $8CA4
    inc     temp0                   ; $8CA6  next square
    lda     temp0                   ; $8CA8
    and     #$0F                    ; $8CAA  16 done?
    bne     @square                 ; $8CAC
    lda     #$FF                    ; $8CAE  end
    sta     ppuBuffer0+35           ; $8CB0
    lda     overworldDrawAddrLo     ; $8CB3  the next tile row
    clc                             ; $8CB5
    adc     #$20                    ; $8CB6
    sta     overworldDrawAddrLo     ; $8CB8
    lda     overworldDrawAddrHi     ; $8CBA
    adc     #$00                    ; $8CBC
    sta     overworldDrawAddrHi     ; $8CBE
    and     #$03                    ; $8CC0  into the attribute table (row 30)?
    cmp     #$03                    ; $8CC2
    bne     @done                   ; $8CC4
    lda     overworldDrawAddrLo     ; $8CC6
    and     #$F0                    ; $8CC8
    cmp     #$C0                    ; $8CCA
    bcc     @done                   ; $8CCC
    lda     overworldDrawAddrLo     ; $8CCE  yes: the top
    and     #$1F                    ; $8CD0
    sta     overworldDrawAddrLo     ; $8CD2
    lda     overworldDrawAddrHi     ; $8CD4  of the other nametable
    eor     #$08                    ; $8CD6
    and     #$F8                    ; $8CD8
    sta     overworldDrawAddrHi     ; $8CDA

@done:
    rts                             ; $8CDC

Sprite0Init:
    .byte   $0E, $C5, $21, $6A                                              ; $8CDD

; ---------------------------------------------------------------------------
; SideView_Start
;
; Start side view play: place sprite 0 for the status bar split
; (Sprite0Init), clear the spell, object and PPU buffers, restore the
; scroll for areaStartPage from the SRAM page tables, reseed rng, start
; the area's music and turn rendering on.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
SideView_Start:
    ldy     #$03                    ; $8CE1  sprite 0 (Sprite0Init): the split's marker

@loop:
    lda     Sprite0Init,y           ; $8CE3
    sta     oamBuffer,y             ; $8CE6
    dey                             ; $8CE9
    bpl     @loop                   ; $8CEA
    lda     #$06                    ; $8CEC  sprites and background on
    sta     ppuMaskExtra            ; $8CEE
    ldy     #$00                    ; $8CF1  a = 0:
    tya                             ; $8CF3
    sta     spellActive             ; $8CF4  no spells

@loop2:
    sta     ppuPage,y               ; $8CF7  clear $0300-$03FF (the PPU buffers)
    sta     overworldBuffer+$00,y   ; $8CFA  and $0400-$04FF
    dey                             ; $8CFD
    bne     @loop2                  ; $8CFE
    sta     scrollFrozen            ; $8D00  scrolling allowed
    sta     spellFlash              ; $8D03  no flash
    dey                             ; $8D06  $FF:
    sty     ppuBuffer1              ; $8D07  end the three buffers' lists
    sty     ppuBuffer2              ; $8D0A
    sty     ppuBuffer0              ; $8D0D
    ldy     areaStartPage           ; $8D10  the entry slot's saved scroll:
    tya                             ; $8D13
    pha                             ; $8D14
    lda     sramEntryLeftPage,y     ; $8D15  the column pages at the edges,
    sta     columnPage              ; $8D18
    lda     sramEntryRightPage,y    ; $8D1B
    sta     columnPage+1            ; $8D1E
    lda     sramEntryLeftColumn,y   ; $8D21  their columns,
    sta     columnIndex             ; $8D24
    lda     sramEntryRightColumn,y  ; $8D27
    sta     columnIndex+1           ; $8D2A
    lda     sramEntryScrollDir,y    ; $8D2D  its direction,
    sta     scrollDir               ; $8D30
    sta     columnDrawDir           ; $8D33
    lda     sramEntryScrollXHi,y    ; $8D36  the scroll page,
    sta     scrollXHi               ; $8D39
    and     #$01                    ; $8D3C  (its nametable)
    sta     playfieldNametable      ; $8D3E
    lda     sramEntryPpuScrollX,y   ; $8D41  the fine scroll,
    sta     a:ppuScrollX            ; $8D44
    lda     sramEntryScrollX,y      ; $8D47  and scrollX
    sta     scrollX                 ; $8D4A
    and     #$10                    ; $8D4D  (the half metatile)
    sta     columnScroll            ; $8D4F
    lda     #$00                    ; $8D52  from the first column step
    sta     columnDrawStep          ; $8D54
    jsr     Scroll_SetRightEdge     ; $8D57  the column at the right edge
    pla                             ; $8D5A
    tay                             ; $8D5B
    lda     #$A5                    ; $8D5C  the RNG's first byte: $A5
    sta     rng                     ; $8D5E
    inc     nmiFlag                 ; $8D61  (nmiFlag, which has no effect)
    lda     areaMusic               ; $8D64  the area's music
    ; Ten nops: probably code removed late in development.
    nop                             ; $8D67
    nop                             ; $8D68
    nop                             ; $8D69
    nop                             ; $8D6A
    nop                             ; $8D6B
    nop                             ; $8D6C
    nop                             ; $8D6D
    nop                             ; $8D6E
    nop                             ; $8D6F
    nop                             ; $8D70
    sta     musicRequest            ; $8D71  start it
    lda     #$00                    ; $8D73  (once)
    sta     areaMusic               ; $8D75
    jmp     Game_UnblankAndNextMode ; $8D78  screen on, next mode

; Magic cost of each spell (SPELL_*) at each magic level 1-8, 8 bytes per
; spell.
SpellCosts:
    .byte   $40, $30, $30, $20, $20, $20, $20, $20, $60, $50, $40, $40, $28, $20, $18, $10; $8D7B
    .byte   $8C, $8C, $78, $78, $64, $64, $64, $64, $A0, $A0, $78, $78, $50, $50, $50, $50; $8D8B
    .byte   $F0, $A0, $78, $3C, $20, $20, $20, $20, $F0, $F0, $A0, $60, $50, $40, $30, $20; $8D9B
    .byte   $F0, $E0, $C0, $A0, $60, $40, $30, $20, $F0, $F0, $F0, $F0, $F0, $F0, $C8, $80; $8DAB

SpellFlags:
    .byte   $01, $02, $04, $08, $10, $20, $40, $80                          ; $8DBB

; ---------------------------------------------------------------------------
; Spell_Update
;
; Side view: spells, once per frame (called from Mode_SideView).
; Unless a dialog is open or the game is paused, Select casts the spell at
; spellCursor, if it is owned, not already the last spell cast, and Link
; has enough magic (SpellCosts, by magic level): the cost is taken from
; statMeter, the spell's bit is set in spellActive, and the screen flashes
; (spellFlash).  Then update Link's palette and run the effect of each
; active spell (Spell_RunEffect).
;
; QUIRK: a spell that costs one more than the magic left is still cast, and
; leaves the magic at 0.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Spell_Update:
    lda     dialogType              ; $8DC3  a dialog,
    ora     pauseState              ; $8DC6  the pause menu
    ora     gameFrozen              ; $8DC9  or a scripted event:
    bne     @effects                ; $8DCB  no casting
    ldy     spellCursor             ; $8DCD  the selected spell + 1
    iny                             ; $8DD0
    cpy     spellLastCast           ; $8DD1  just cast (until the menu is opened again)?
    beq     @effects                ; $8DD4
    lda     joypadPressed           ; $8DD6  Select pressed?
    and     #$20                    ; $8DD8
    beq     @effects                ; $8DDA
    ldy     spellCursor             ; $8DDC  owned?
    lda     spellOwned,y            ; $8DDF
    beq     @effects                ; $8DE2
    tya                             ; $8DE4  its row of SpellCosts:
    asl     a                       ; $8DE5  spell x 8
    asl     a                       ; $8DE6
    asl     a                       ; $8DE7
    adc     statLevel+STAT_MAGIC    ; $8DE8  + magic level (1-8; carry clear)
    tay                             ; $8DEB
    lda     statMeter               ; $8DEC  magic - cost
    sec                             ; $8DEF
    sbc     SpellCosts - 1,y        ; $8DF0  y = spell * 8 + magic level (1-8)
    bcc     @short                  ; $8DF3  short:

@cast:
    sta     statMeter               ; $8DF5  new magic
    ldy     spellCursor             ; $8DF8  set the spell's bit
    lda     SpellFlags,y            ; $8DFB
    ora     spellActive             ; $8DFE
    sta     spellActive             ; $8E01
    iny                             ; $8E04  remember it
    sty     spellLastCast           ; $8E05
    lda     hudRedraw               ; $8E08  redraw the magic meter
    ora     #$80                    ; $8E0B
    sta     hudRedraw               ; $8E0D
    lda     #$20                    ; $8E10  flash for $20 frames,
    cpy     #$06                    ; $8E12  Reflect, Spell and Thunder (cursor 5-7)
    bcc     @setFlash               ; $8E14
    ora     #$80                    ; $8E16  flash the backdrop too

@setFlash:
    sta     spellFlash              ; $8E18
    lda     #$04                    ; $8E1B  the spell sound
    sta     sfxRequest              ; $8E1D

@effects:
    lda     #$00                    ; $8E1F  the jump spell is set again below
    sta     jumpSpellActive         ; $8E21
    jsr     Link_UpdatePalette      ; $8E23  Link's palette (flashing)
    ldy     #$07                    ; $8E26  each active spell, Thunder down to Shield:

@loop:
    tya                             ; $8E28
    pha                             ; $8E29
    lda     SpellFlags,y            ; $8E2A
    bit     spellActive             ; $8E2D
    beq     @nextSpell              ; $8E30
    jsr     Spell_RunEffect         ; $8E32

@nextSpell:
    pla                             ; $8E35
    tay                             ; $8E36
    dey                             ; $8E37
    bpl     @loop                   ; $8E38
    rts                             ; $8E3A

@short:
    cmp     #$FF                    ; $8E3B  exactly one short (-1)?
    bne     @effects                ; $8E3D  no
    lda     #$00                    ; $8E3F  QUIRK: cast anyway, magic 0
    jmp     @cast                   ; $8E41

; ---------------------------------------------------------------------------
; Spell_RunEffect
;
; Run the per-frame effect of active spell y (SPELL_*).
;
; In:      y = spell
; Status:  confirmed (dispatch)
; ---------------------------------------------------------------------------
Spell_RunEffect:
    tya                             ; $8E44  by spell
    jsr     JumpTable               ; $8E45
; (inline jump table)
    .word   Spell_ShieldEffect      ; $8E48  (not observed)
    .word   Spell_JumpEffect        ; $8E4A
    .word   Spell_LifeEffect        ; $8E4C  (not observed)
    .word   Spell_FairyEffect       ; $8E4E
    .word   Spell_FireEffect        ; $8E50
    .word   Spell_ReflectEffect     ; $8E52
    .word   Spell_SpellEffect       ; $8E54
    .word   Spell_ThunderEffect     ; $8E56

; ---------------------------------------------------------------------------
; Spell_JumpEffect
;
; The jump spell: each frame, set jumpSpellActive for Link_UpdateJump's
; higher jump (Spell_Update clears it first).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Spell_JumpEffect:
    lda     #$01                    ; $8E58  higher jumps this frame (Link_UpdateJump)
    sta     jumpSpellActive         ; $8E5A
    rts                             ; $8E5C

; ---------------------------------------------------------------------------
; Spell_LifeEffect
;
; The life spell: once, add 48 to the life still to be refilled
; (statMeterPending+1, at most 255), and clear the spell's bit.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
; (code below not executed in the test movies)
Spell_LifeEffect:
    lda     spellActive             ; $8E5D  once:
    and     #$FB                    ; $8E60  clear the Life bit
    sta     spellActive             ; $8E62
    lda     statMeterPending+1      ; $8E65  add 48 to the life to refill
    clc                             ; $8E68
    adc     #$30                    ; $8E69
    bcc     @setLife                ; $8E6B  (at most 255)
    lda     #$FF                    ; $8E6D

@setLife:
    sta     statMeterPending+1      ; $8E6F
    rts                             ; $8E72
; (end of code not executed in the test movies)

; ---------------------------------------------------------------------------
; Spell_SpellEffect
;
; The SPELL spell: outside the towns, turn the enemies into Bots
; (Spell_TurnEnemiesToBots).  In a town, only on New Kasuto's east street
; (area $14): freeze the game and open the big door (BigDoor_Update)
; each frame; elsewhere in a town it does nothing.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Spell_SpellEffect:
    lda     currentWorld            ; $8E73  the overworld's areas (world 0)
    beq     @bots                   ; $8E76
    cmp     #$03                    ; $8E78  or the palaces (3-5):
    bcs     @bots                   ; $8E7A  turn the enemies into Bots
    lda     areaId                  ; $8E7C  a town: New Kasuto's east street ($14)?
    cmp     #$14                    ; $8E7F
    bne     Spell_ShieldEffectDone  ; $8E81  no: nothing (the bit stays set)
    lda     #$01                    ; $8E83  yes: freeze the game
    sta     gameFrozen              ; $8E85
    jmp     BigDoor_Update          ; $8E87  and open the big door
; (code below not executed in the test movies)

@bots:
    jmp     Spell_TurnEnemiesToBots ; $8E8A

; ---------------------------------------------------------------------------
; Spell_ShieldEffect
;
; The shield spell: each frame, Link's shield color ($16) and
; shieldSpellActive (damage halved, Link_TakeDamage).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Spell_ShieldEffect:
    lda     #$16                    ; $8E8D  Link's shield color,
    sta     sramLinkPalette3+4      ; $8E8F
    sta     shieldSpellActive       ; $8E92  halve damage (Link_TakeDamage)

; ---------------------------------------------------------------------------
; Spell_ShieldEffectDone
;
; Return (shared tail of Spell_ShieldEffect).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Spell_ShieldEffectDone:
    rts                             ; $8E95
; (end of code not executed in the test movies)

; ---------------------------------------------------------------------------
; Spell_ReflectEffect
;
; The reflect spell: each frame, set reflectSpellActive (the shield
; reflects shots, Link_CheckShield).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Spell_ReflectEffect:
    lda     #$01                    ; $8E96  shield reflects (Link_CheckShield)
    sta     reflectSpellActive      ; $8E98
    rts                             ; $8E9B
    .byte   $F4, $F4, $30, $31, $30, $31, $30, $31, $F4, $F4, $F4, $30, $31, $30, $49, $4A; $8E9C
    .byte   $31, $30, $31, $F4, $30, $31, $30, $31, $FF, $FF, $30, $31, $30, $31; $8EAC

BigDoorString:
    .byte   $23, $F5, $43, $5F, $23, $ED, $43, $FF, $23, $E5, $43, $FF, $23, $DD, $43, $FF; $8EBA
    .byte   $23, $D5, $43, $FF, $23, $CD, $43, $FF                          ; $8ECA

BigDoorRowPtrs:
    .byte   $9C                                                             ; $8ED2
    .byte   $8E, $A6, $8E, $B0, $8E                                         ; $8ED3

; ---------------------------------------------------------------------------
; BigDoor_Update
;
; The big door on New Kasuto's east street, run each frame by the SPELL
; spell there (Spell_SpellEffect, with gameFrozen set): the first frame
; sets its attributes (BigDoorString) and plays shared effect $10; then
; every 16 frames bigDoorCounter counts up and the door's three pattern
; rows (BigDoorRowPtrs) are drawn one row higher; at 15 the open doorway
; goes into the tile map (BigDoor_DrawOpen), and at 16 the game is
; unfrozen.  (Checked with a scripted cast in area $14 of the East Hyrule
; towns: 272 frames, then a dark doorway in the stone building.)
;
; Status:  confirmed
; ---------------------------------------------------------------------------
BigDoor_Update:
    lda     bigDoorCounter          ; $8ED8  16 steps done?
    cmp     #$10                    ; $8EDB
    bne     @notDone                ; $8EDD
    lda     #$00                    ; $8EDF  yes: unfreeze
    sta     gameFrozen              ; $8EE1
    rts                             ; $8EE3

@notDone:
    cmp     #$0F                    ; $8EE4  step 15:
    bne     @checkFirst             ; $8EE6
    jsr     BigDoor_DrawOpen        ; $8EE8  the open door in the tile map

@checkFirst:
    lda     bigDoorState            ; $8EEB  the first frame:
    bne     @step                   ; $8EEE
    lda     #$10                    ; $8EF0  shared effect $10
    sta     sfxRequest              ; $8EF2
    sta     bigDoorState            ; $8EF4  (once)

@step:
    lda     #$54                    ; $8EF7  tile $54 at map row 11, column 13
    sta     sramAreaTiles+189       ; $8EF9
    lda     frameCounter            ; $8EFC  every 16 frames:
    and     #$0F                    ; $8EFE
    bne     @done                   ; $8F00
    lda     #$23                    ; $8F02  from PPU $2336,
    sta     temp0                   ; $8F04
    lda     #$36                    ; $8F06
    sta     temp1                   ; $8F08
    ldx     #$00                    ; $8F0A
    lda     bigDoorCounter          ; $8F0C  the door's three rows, one row higher each step:

@loop:
    pha                             ; $8F0F
    cmp     #$03                    ; $8F10  rows 0-2 of the pattern only
    bpl     @rowUp                  ; $8F12
    asl     a                       ; $8F14  its row
    tay                             ; $8F15
    lda     BigDoorRowPtrs,y        ; $8F16
    sta     temp2                   ; $8F19
    lda     BigDoorRowPtrs+1,y      ; $8F1B
    sta     temp3                   ; $8F1E
    jsr     Ppu_QueueString10       ; $8F20  queue it
    inx                             ; $8F23
    inx                             ; $8F24
    inx                             ; $8F25

@rowUp:
    lda     temp1                   ; $8F26  one row up
    sec                             ; $8F28
    sbc     #$20                    ; $8F29
    sta     temp1                   ; $8F2B
    bcs     @nextRow                ; $8F2D
    dec     temp0                   ; $8F2F

@nextRow:
    pla                             ; $8F31  the next pattern row
    sec                             ; $8F32
    sbc     #$01                    ; $8F33
    bpl     @loop                   ; $8F35
    lda     bigDoorStep             ; $8F37  the first time:
    bne     @end                    ; $8F3A
    ldx     #$00                    ; $8F3C  the door's attributes (BigDoorString)

@loop2:
    lda     BigDoorString,x         ; $8F3E
    sta     ppuBuffer1,x            ; $8F41
    inx                             ; $8F44
    cpx     #$18                    ; $8F45
    bne     @loop2                  ; $8F47
    inc     bigDoorStep             ; $8F49
    dec     bigDoorCounter          ; $8F4C  (counted back up below)

@end:
    lda     #$FF                    ; $8F4F  end
    sta     ppuBuffer1,x            ; $8F51
    inc     bigDoorCounter          ; $8F54  next step

@done:
    rts                             ; $8F57

; ---------------------------------------------------------------------------
; Ppu_QueueString10
;
; Queue a PPU string of 10 bytes from (temp2) to PPU address temp0:temp1 in
; ppuBuffer1 at x, and select ppuBuffer1 for the next NMI.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Ppu_QueueString10:
    lda     #$01                    ; $8F58  send ppuBuffer1
    sta     ppuStringSelect         ; $8F5A
    lda     temp0                   ; $8F5D  address
    sta     ppuBuffer1,x            ; $8F5F
    lda     temp1                   ; $8F62
    sta     ppuBuffer1+1,x          ; $8F64
    lda     #$0A                    ; $8F67  10 bytes
    sta     ppuBuffer1+2,x          ; $8F69
    ldy     #$00                    ; $8F6C

@loop:
    lda     (temp2),y               ; $8F6E
    sta     ppuBuffer1+3,x          ; $8F70
    inx                             ; $8F73
    iny                             ; $8F74
    cpy     #$0A                    ; $8F75
    bne     @loop                   ; $8F77
    rts                             ; $8F79

BigDoorOpenTopTiles:
    .byte   $E1, $DF, $E0, $DF, $DE                                         ; $8F7A

BigDoorOpenTiles:
    .byte   $E2, $E2, $D6, $E2, $E2                                         ; $8F7F

; ---------------------------------------------------------------------------
; BigDoor_DrawOpen
;
; Draw the opened big door into the area tile map: five columns of tiles
; from BigDoorOpenTopTiles/BigDoorOpenTiles, down to tile row $B0.  Called by
; BigDoor_Update when bigDoorCounter reaches $0F.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
BigDoor_DrawOpen:
    lda     #$00                    ; $8F84  the tile map's page 0 ($6000)
    sta     temp14                  ; $8F86
    lda     #$60                    ; $8F88
    sta     temp15                  ; $8F8A
    lda     #$3B                    ; $8F8C  from column $3B (row 3)
    sta     temp2                   ; $8F8E
    ldx     #$04                    ; $8F90  5 columns

@column:
    ldy     temp2                   ; $8F92  the column's top tile,
    lda     BigDoorOpenTopTiles,x   ; $8F94

@tileDown:
    jsr     AreaMap_PutTileDown     ; $8F97  then down
    cmp     #$B0                    ; $8F9A  to row 11
    bcs     @nextColumn             ; $8F9C
    lda     BigDoorOpenTiles,x      ; $8F9E  the doorway
    jmp     @tileDown               ; $8FA1

@nextColumn:
    inc     temp2                   ; $8FA4  next column
    dex                             ; $8FA6
    bpl     @column                 ; $8FA7
    rts                             ; $8FA9

FallPaletteString:
    .byte   $3F, $00, $04, $0F, $2C, $1C, $0C, $FF                          ; $8FAA

FallPaletteColors:
    .byte   $2C                                                             ; $8FB2
    .byte   $1C                                                             ; $8FB3
    .byte   $0C, $2C, $1C                                                   ; $8FB4

; ---------------------------------------------------------------------------
; Mode_FallAnimate
;
; gameMode $0F: show Link falling down the blank screen, 2 pixels per
; frame in the hurt pose, with a black silhouette of himself (object 1's
; draw in palette 1) 8 pixels right and about 9 higher, while the
; background's three colors rotate every 2 frames.  Below Y $E8, load the
; area (gameMode 8) in the overworld's areas, or leave it (gameMode $10)
; elsewhere.  (Seen at frame 22785 of the no-glitch movie.)
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Mode_FallAnimate:
    inc     objY                    ; $8FB7  2 pixels per frame
    inc     objY                    ; $8FB9
    lda     objY                    ; $8FBB  his shadow, 8 or 9 pixels higher (9 seen)
    sbc     #$08                    ; $8FBD
    sta     objY+1                  ; $8FBF
    lda     #$78                    ; $8FC1  at X $78
    sta     drawScreenX             ; $8FC3
    lda     #$80                    ; $8FC5  the shadow at X $80
    sta     drawScreenX+1           ; $8FC7
    lda     #$0A                    ; $8FC9  both hurt (pose $0A)
    sta     objState                ; $8FCB
    sta     objState+1              ; $8FCD
    lda     linkWalkDir             ; $8FCF  facing the same way
    sta     darkLinkWalkDir         ; $8FD1
    lda     #$30                    ; $8FD3  the second at oamBuffer $30
    sta     objOamOffset+1          ; $8FD5
    ldx     #$00                    ; $8FD7  on screen
    stx     drawOffscreen           ; $8FD9
    stx     drawOffscreen+1         ; $8FDB
    inx                             ; $8FDD  drawn as object 1 (swordOwner 1) in palette 1: black
    stx     swordOwner              ; $8FDE
    stx     extraSpriteAttrs        ; $8FE0
    jsr     Link_DrawBody           ; $8FE3  draw it
    lda     #$08                    ; $8FE6  Link at oamBuffer $08
    sta     objOamOffset            ; $8FE8
    ldx     #$00                    ; $8FEA
    stx     swordOwner              ; $8FEC
    jsr     Link_DrawBody           ; $8FEE
    lda     a:frameCounter          ; $8FF1  every other frame:
    and     #$01                    ; $8FF4
    bne     @done                   ; $8FF6
    ldx     #$07                    ; $8FF8  the background palette ($3F00)

@loop:
    lda     FallPaletteString,x     ; $8FFA
    sta     ppuBuffer0,x            ; $8FFD
    dex                             ; $9000
    bpl     @loop                   ; $9001
    inc     fallStep                ; $9003  rotating
    ldy     fallStep                ; $9006
    cpy     #$03                    ; $9009
    bcc     @setColors              ; $900B
    ldy     #$00                    ; $900D
    sty     fallStep                ; $900F

@setColors:
    lda     FallPaletteColors,y     ; $9012  its three colors
    sta     ppuBuffer0+4            ; $9015
    lda     FallPaletteColors+1,y   ; $9018
    sta     ppuBuffer0+5            ; $901B
    lda     FallPaletteColors+2,y   ; $901E
    sta     ppuBuffer0+6            ; $9021
    lda     objY                    ; $9024  below Y $E8?
    cmp     #$E8                    ; $9026
    bcc     @done                   ; $9028
    inc     renderingOff            ; $902A  yes: screen off,
    lda     #$08                    ; $902D  the overworld's areas: gameMode 8 (load the area)
    ldy     currentWorld            ; $902F
    beq     @setMode                ; $9032
    lda     #$10                    ; $9034  elsewhere: $10 (leave the area)

@setMode:
    sta     gameMode                ; $9036

@done:
    rts                             ; $9039

; ---------------------------------------------------------------------------
; Link_Run
;
; Run Link for one frame in the side view, by linkMode (LINK_MODE_*).
;
; Status:  confirmed (dispatch)
; ---------------------------------------------------------------------------
Link_Run:
    lda     linkMode                ; $903A  by mode
    jsr     JumpTable               ; $903C
; (inline jump table)
    .word   Link_EnterArea          ; $903F
    .word   Link_Control            ; $9041
    .word   Link_Sink               ; $9043

AreaEntryXOffsets:
    .byte   $08, $D8                                                        ; $9045

; ---------------------------------------------------------------------------
; Link_EnterArea
;
; LINK_MODE_ENTER: place Link in a newly entered area, at the left or right
; edge (areaEntrySide) facing inward and walking in for 9 frames, or at the
; X saved with the scroll he returns to (areaStartPage 4 and up: an
; elevator, which then puts him at X $70, a fall, or back out of a door).
; Place the elevator and locked door, limit the scroll of a two page area
; to the pair of pages he is on (0-1 or 2-3; both seen in the 100% movie),
; clear his state, start the area's music and go to LINK_MODE_CONTROL.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Link_EnterArea:
    lda     #$03                    ; $9047  standing,
    sta     objState                ; $9049
    lsr     a                       ; $904B  a = 1:
    sta     objYHi                  ; $904C  on screen,
    sta     linkStanding            ; $904E  standing,
    lsr     a                       ; $9050  a = 0:
    sta     extraSpriteAttrs        ; $9051  normal palette,
    sta     objYVelocity            ; $9054  not falling
    ldx     #$07                    ; $9057  no projectiles (slots 7-14)

@loop:
    sta     objState+7,x            ; $9059
    dex                             ; $905B
    bpl     @loop                   ; $905C
    ldy     areaStartPage           ; $905E  starting on a map page
    cpy     #$04                    ; $9061  (0-3)
    bcs     @saved                  ; $9063  no: a saved scroll (4 and up)
    ldy     areaEntrySide           ; $9065  at the screen's left or right edge:
    lda     scrollX                 ; $9068  scrollX + 8 or + $D8
    adc     AreaEntryXOffsets,y     ; $906B
    sta     objX                    ; $906E
    lda     scrollXHi               ; $9070  its page
    adc     #$00                    ; $9073
    ldx     #$08                    ; $9075  walk in for 9 frames
    bne     @setPage                ; $9077  (always)

@saved:
    lda     entryLinkX,y            ; $9079  the X saved with the entry scroll
    sta     objX                    ; $907C
    lda     entryLinkXHi,y          ; $907E  (x = $FF + 1: no walking in)

@setPage:
    sta     objXHi                  ; $9081  page
    inx                             ; $9083
    stx     timerFast+TIMER_LINK_ENTER ; $9084  walk in (TIMER_LINK_ENTER)
    ldy     areaEntrySide           ; $9087  face inward: 1 right from the left,
    iny                             ; $908A  2 left from the right
    sty     objFacing               ; $908B
    sty     linkWalkDir             ; $908D
    lda     linkFallingIn           ; $908F  falling in from above?
    bne     @objects                ; $9092
    jsr     Link_PlaceOnGround      ; $9094  no: stand him on the floor

@objects:
    jsr     Area_PlaceElevatorAndDoor ; $9097  elevator, door or fairy
    ldy     areaLastPage            ; $909A  a two page area (areaLastPage 1)?
    dey                             ; $909C
    bne     @clear                  ; $909D
    lda     objXHi                  ; $909F  yes: limit the scroll to his pair of pages
    and     #$02                    ; $90A1  (pages 0-1 or 2-3)
    tay                             ; $90A3
    sty     sramScrollMinPage+1     ; $90A4  min page
    iny                             ; $90A7
    sty     sramScrollMaxPage+1     ; $90A8  max page

@clear:
    lda     #$00                    ; $90AB  a = 0:
    sta     linkFallingIn           ; $90AD
    sta     enteredVertically       ; $90B0
    sta     drawOffscreen           ; $90B3
    sta     linkButtonsPressed      ; $90B5
    sta     linkDirHeld             ; $90B8
    sta     linkAttackFrame         ; $90BB
    sta     objXVelocity            ; $90BE
    sta     reflectSpellActive      ; $90C0
    sta     shieldSpellActive       ; $90C3
    ldy     chimneyTimer            ; $90C6  down a chimney?
    beq     @control                ; $90C9
    sta     objY                    ; $90CB  yes: at the top of the screen,
    sta     timerFast+TIMER_LINK_ENTER ; $90CD  not walking in,
    sta     chimneyTimer            ; $90D0
    lda     #$50                    ; $90D3  at X $50
    sta     objX                    ; $90D5

@control:
    inc     linkMode                ; $90D7  LINK_MODE_CONTROL
    lda     #$2A                    ; $90D9  Link's normal shield color
    sta     sramLinkPalette3+4      ; $90DB
    lda     areaMusic               ; $90DE  the area's music
