; ---------------------------------------------------------------------------
; Hud_DrawRightHalf
;
; Queue the right half of the status bar from HudRightTemplate: the life
; level after LIFE- ($2052), the life meter (from $206E, $C8 empty, $C7
; full), the experience ($2076-$2079) and experienceNext's first three
; digits ($207B-$207D); its ones digit is the name table's '0' (every
; cost is a multiple of 50).  (Checked with a screenshot: 1079/0050.)
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Hud_DrawRightHalf:
    lda     hudRedraw               ; $9723  clear bit 6: life drawn
    and     #$BF                    ; $9726
    sta     hudRedraw               ; $9728
    ldy     ppuBuffer0Len           ; $972B

@loop:
    lda     HudRightTemplate,x      ; $972E  copy HudRightTemplate
    sta     ppuBuffer0,y            ; $9731
    iny                             ; $9734
    inx                             ; $9735
    cpx     #$18                    ; $9736  (24 bytes; its $FF is LevelUpCostHi's first byte)
    bcc     @loop                   ; $9738
    tya                             ; $973A  the end, for later
    pha                             ; $973B
    ldy     ppuBuffer0Len           ; $973C  the string's start
    lda     statLevel+STAT_LIFE     ; $973F  life level digit,
    clc                             ; $9742
    adc     #$D0                    ; $9743
    sta     ppuBuffer0+3,y          ; $9745  after LIFE- (PPU $2052)
    lda     experience              ; $9748  experience as digits:
    sta     temp0                   ; $974B
    lda     experience+1            ; $974D
    jsr     Math_ToDigits           ; $9750  thousands in temp1, hundreds in temp0, tens in y, ones in a
    pha                             ; $9753
    tya                             ; $9754
    ldy     ppuBuffer0Len           ; $9755
    sta     ppuBuffer0+17,y         ; $9758  (PPU $2076-$2079)
    lda     temp0                   ; $975B
    sta     ppuBuffer0+16,y         ; $975D
    lda     temp1                   ; $9760
    sta     ppuBuffer0+15,y         ; $9762
    pla                             ; $9765
    sta     ppuBuffer0+18,y         ; $9766
    lda     experienceNext          ; $9769  experienceNext,
    sta     temp0                   ; $976C
    lda     experienceNext+1        ; $976E
    jsr     Math_ToDigits           ; $9771  as digits
    tya                             ; $9774
    ldy     ppuBuffer0Len           ; $9775
    sta     ppuBuffer0+22,y         ; $9778  its thousands, hundreds and tens (PPU $207B-$207D);
    lda     temp0                   ; $977B
    sta     ppuBuffer0+21,y         ; $977D  the ones digit is always 0,
    lda     temp1                   ; $9780
    sta     ppuBuffer0+20,y         ; $9782  left in the name table
    ldy     ppuBuffer0Len           ; $9785
    lda     statContainers+STAT_METER_LIFE ; $9788  heart containers:
    tax                             ; $978B
    clc                             ; $978C  from the last one back
    adc     ppuBuffer0Len           ; $978D
    tay                             ; $9790
    dey                             ; $9791
    lda     #$C8                    ; $9792  empty blocks (from PPU $206E)

@loop2:
    sta     ppuBuffer0+7,y          ; $9794
    dey                             ; $9797
    dex                             ; $9798
    bne     @loop2                  ; $9799
    iny                             ; $979B  the first block
    lda     statMeter+STAT_METER_LIFE ; $979C  life as shown
    sta     statMeterDisplay+1      ; $979F
    lsr     a                       ; $97A2  / 32: full blocks
    lsr     a                       ; $97A3
    lsr     a                       ; $97A4
    lsr     a                       ; $97A5
    lsr     a                       ; $97A6
    sta     temp0                   ; $97A7

@fullBlocks:
    dec     temp0                   ; $97A9  each full block:
    bmi     @finish                 ; $97AB
    lda     #$C7                    ; $97AD  a full life block
    sta     ppuBuffer0+7,y          ; $97AF
    iny                             ; $97B2
    jmp     @fullBlocks             ; $97B3

@finish:
    jmp     Hud_FinishHalf          ; $97B6

MeterSpritePtr:
    .byte   $F8                                                             ; $97B9
    .byte   $02                                                             ; $97BA

; ---------------------------------------------------------------------------
; Hud_DrawMeterSprites
;
; Draw the two sprites (oamBuffer $F8 and $FC) that mark the end of the
; magic and life meters' fill, inside the last partly filled block: Y $0F,
; X = the meter's left edge + meter / 4, palette 1, behind the
; background.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Hud_DrawMeterSprites:
    ldx     #$01                    ; $97BB  life, then magic
    lda     MeterSpritePtr          ; $97BD  at oamBuffer $F8 (sprites 62-63)
    sta     temp0                   ; $97C0
    lda     MeterSpritePtr+1        ; $97C2
    sta     temp1                   ; $97C5

@loop:
    txa                             ; $97C7
    pha                             ; $97C8
    asl     a                       ; $97C9  x 4: its sprite
    asl     a                       ; $97CA
    tay                             ; $97CB
    txa                             ; $97CC
    and     #$01                    ; $97CD  (meter 0 magic, 1 life)
    tax                             ; $97CF
    lda     #$0F                    ; $97D0  Y $0F
    sta     (temp0),y               ; $97D2
    iny                             ; $97D4
    lda     MeterSpriteTiles,x      ; $97D5  the meter's tip tile
    sta     (temp0),y               ; $97D8
    iny                             ; $97DA
    lda     #$21                    ; $97DB  palette 1, behind the background
    sta     (temp0),y               ; $97DD
    iny                             ; $97DF
    lda     statMeterDisplay,x      ; $97E0  X: meter / 4 (8 pixels per 32)
    lsr     a                       ; $97E3
    lsr     a                       ; $97E4
    clc                             ; $97E5
    adc     MeterSpriteXOffsets,x   ; $97E6  + the meter's left edge
    sta     (temp0),y               ; $97E9
    pla                             ; $97EB
    tax                             ; $97EC
    dex                             ; $97ED
    bpl     @loop                   ; $97EE
    rts                             ; $97F0

; ---------------------------------------------------------------------------
; Spell_FireEffect
;
; The fire spell: each frame, fire a flame with each stroke of the sword
; (LinkProjectile_TrySpawn), in slot 13, or 13-14 from attack level 4.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Spell_FireEffect:
    ldx     #$01                    ; $97F1  slots 13-14
    lda     statLevel               ; $97F3  from attack level 4
    cmp     #$04                    ; $97F6
    bcs     LinkProjectile_TrySpawn ; $97F8  (x = 1)

LinkProjectile_Spawn:
    ldx     #$00                    ; $97FA  slot 13 only

; ---------------------------------------------------------------------------
; LinkProjectile_TrySpawn
;
; Spawn a projectile for Link in a free slot among 13..13+x, on the frame
; of his attack when the sword is out; carry set if spawned.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
LinkProjectile_TrySpawn:
    ldy     linkAttackFrame         ; $97FC  the stroke's frame
    dey                             ; $97FF  (standing 2, crouching 1)
    cpy     linkAttackStanding      ; $9800
    bne     @none                   ; $9803
    lda     timerFast+TIMER_LINK_ATTACK ; $9805  its first frame (timer 6 - 1)?
    cmp     #$05                    ; $9808
    bne     @none                   ; $980A

@loop:
    lda     objState+13,x           ; $980C  a free slot?
    beq     LinkProjectile_Start    ; $980E
    dex                             ; $9810
    bpl     @loop                   ; $9811

@none:
    clc                             ; $9813  none: carry clear
    rts                             ; $9814

LinkProjectileYOffsets:
    .byte   $0D, $04                                                        ; $9815
    .byte   $09                                                             ; $9817

LinkProjectileSpeeds:
    .byte   $FF, $20, $E0                                                   ; $9818

; ---------------------------------------------------------------------------
; LinkProjectile_Start
;
; Start Link projectile x beside Link, moving in his direction.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
LinkProjectile_Start:
    inc     objState+13,x           ; $981B  state 1, moving
    lda     objX                    ; $981D  X + $0D (carry set)
    adc     #$0C                    ; $981F
    sta     objX+13,x               ; $9821
    lda     objXHi                  ; $9823
    adc     #$00                    ; $9825
    sta     objXHi+13,x             ; $9827
    lda     objY                    ; $9829  Y + $0D crouching,
    ldy     a:linkStanding          ; $982B
    adc     LinkProjectileYOffsets,y ; $982E  + 4 standing
    sta     objY+13,x               ; $9831
    lda     #$01                    ; $9833  on screen
    sta     objYHi+13,x             ; $9835
    lsr     a                       ; $9837  timer 0: the flame
    sta     linkProjectileTimer,x   ; $9838
    ldy     linkWalkDir             ; $983B  the way Link faces
    sty     linkProjectileDir,x     ; $983D
    lda     LinkProjectileSpeeds,y  ; $983F  2 pixels per frame that way
    sta     objXVelocity+13,x       ; $9842
    rts                             ; $9844

LinkProjectileOamOffsets:
    .byte   $38, $40                                                        ; $9845

; ---------------------------------------------------------------------------
; LinkProjectile_Update
;
; At full life (the meter at containers x 32 - 1), fire the sword beam in
; slot 13 (LinkProjectile_Spawn) on the first frame of each stroke, unless
; the fire spell is active (it fires its flame instead): at Link's Y
; standing, 10 pixels lower crouching, flying 2 pixels per frame for 32
; frames (linkProjectileTimer $D2 up to $F2), then sparking for 7 frames.
; Then update Link's projectiles: slot 13, and slot 14 too from attack
; level 4.  (Checked with a scripted attack at full life.)
;
; Status:  confirmed
; ---------------------------------------------------------------------------
LinkProjectile_Update:
    lda     spellActive             ; $9847  the fire spell?
    and     #$10                    ; $984A
    bne     @update                 ; $984C  yes: it fires instead
    lda     statContainers+STAT_METER_LIFE ; $984E  full life:
    asl     a                       ; $9851
    asl     a                       ; $9852
    asl     a                       ; $9853
    asl     a                       ; $9854
    asl     a                       ; $9855  containers x 32
    sec                             ; $9856
    sbc     #$01                    ; $9857  - 1
    cmp     statMeter+STAT_METER_LIFE ; $9859  = the life meter?
    bne     @update                 ; $985C
    jsr     LinkProjectile_Spawn    ; $985E  fire a beam in slot 13
    bcc     @update                 ; $9861  not this frame
    lda     objY                    ; $9863  the beam's Y: Link's Y standing
    ldy     linkAttackStanding      ; $9865
    adc     LinkProjectileYOffsets+2,y ; $9868  ($FF + carry), + $0A crouching
    sta     objY+13,x               ; $986B
    lda     #$D2                    ; $986D  the beam's timer: $D2,
    sta     linkProjectileTimer     ; $986F  counting up to $F2: 32 frames
    lda     sfxRequest+3            ; $9872  the sword chime
    ora     #$08                    ; $9874
    sta     sfxRequest+3            ; $9876

@update:
    ldx     #$00                    ; $9878  slot 13,
    lda     statLevel               ; $987A
    cmp     #$04                    ; $987D  and 14 from attack level 4
    bcc     @updateSlots            ; $987F
    inx                             ; $9881

@updateSlots:
    jsr     LinkProjectile_UpdateOne ; $9882
    dex                             ; $9885
    bmi     LinkProjectile_Done     ; $9886

LinkProjectile_UpdateOne:
    stx     currentObject           ; $9888
    lda     LinkProjectileOamOffsets,x ; $988A  its sprite: $38 or $40
    sta     objOamOffset+13,x       ; $988D
    lda     objState+13,x           ; $988F  unused?
    beq     LinkProjectile_Done     ; $9891
    bmi     LinkProjectile_Spark    ; $9893  sparking ($F2-$FE)?
    lda     linkProjectileTimer,x   ; $9895  a beam?
    beq     @flame                  ; $9898
    inc     linkProjectileTimer,x   ; $989A  count
    cmp     #$F2                    ; $989D  32 frames up?
    beq     LinkProjectile_SetState ; $989F  yes: spark ($F2)
    bne     LinkProjectile_Move     ; $98A1

@flame:
    jsr     LinkProjectile_PlaySound ; $98A3  the flame's sound

; ---------------------------------------------------------------------------
; LinkProjectile_Move
;
; Move Link's projectile x (slot x + 13) and remove it once it leaves the
; screen.
;
; In:      x = Link projectile index
; Status:  confirmed
; ---------------------------------------------------------------------------
LinkProjectile_Move:
    txa                             ; $98A6  its object slot
    clc                             ; $98A7
    adc     #$0D                    ; $98A8
    tax                             ; $98AA
    jsr     Obj_MoveX               ; $98AB  move
    ldy     #$03                    ; $98AE  Link's projectile category
    jsr     Obj_ComputeScreenPos    ; $98B0  screen position
    ldx     currentObject           ; $98B3
    lda     drawOffscreen+3         ; $98B5  off the screen?
    and     #$FC                    ; $98B7
    beq     LinkProjectile_Draw     ; $98B9  no: draw it
    lda     #$00                    ; $98BB  yes: remove it

; ---------------------------------------------------------------------------
; LinkProjectile_SetState
;
; Set Link projectile x's state to a.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
LinkProjectile_SetState:
    sta     objState+13,x           ; $98BD

; ---------------------------------------------------------------------------
; LinkProjectile_Done
;
; Return (shared tail of the Link projectile routines).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
LinkProjectile_Done:
    rts                             ; $98BF

; ---------------------------------------------------------------------------
; LinkProjectile_Draw
;
; Draw Link projectile x (the sword beam, or the fire spell's flame).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
LinkProjectile_Draw:
    ldy     objOamOffset+13,x       ; $98C0  its sprite
    lda     objY+13,x               ; $98C2
    sta     oamBuffer,y             ; $98C4
    lda     linkProjectileDir,x     ; $98C7  facing right (1)
    lsr     a                       ; $98C9
    lda     #$00                    ; $98CA  flips it ($40)
    ror     a                       ; $98CC
    ror     a                       ; $98CD
    sta     temp0                   ; $98CE
    lda     frameCounter            ; $98D0  frame counter bit 2:
    asl     a                       ; $98D2
    asl     a                       ; $98D3
    asl     a                       ; $98D4
    asl     a                       ; $98D5
    asl     a                       ; $98D6
    and     #$80                    ; $98D7  flipped vertically every 4 frames
    ora     temp0                   ; $98D9
    ora     #$01                    ; $98DB  palette 1
    sta     oamBuffer+2,y           ; $98DD
    lda     #$84                    ; $98E0  tile $84, the flame
    sta     oamBuffer+1,y           ; $98E2
    lda     linkProjectileTimer,x   ; $98E5  a beam?
    beq     @setX                   ; $98E8
    lda     #$32                    ; $98EA  tile $32
    sta     oamBuffer+1,y           ; $98EC
    lda     frameCounter            ; $98EF  palette by frame (0-3)
    and     #$03                    ; $98F1
    ora     oamBuffer+2,y           ; $98F3
    and     #$7F                    ; $98F6  no vertical flip
    sta     oamBuffer+2,y           ; $98F8

@setX:
    lda     drawScreenX+3           ; $98FB  its screen X
    sta     oamBuffer+3,y           ; $98FD
    rts                             ; $9900

; ---------------------------------------------------------------------------
; LinkProjectile_PlaySound
;
; The fire's sound, each frame a flame flies (noise effect $40).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
LinkProjectile_PlaySound:
    lda     sfxRequest+1            ; $9901  the fire's sound
    ora     #$40                    ; $9903
    sta     sfxRequest+1            ; $9905
    rts                             ; $9907

; ---------------------------------------------------------------------------
; LinkProjectile_Spark
;
; Link projectile x hit something: move and draw it as a spark
; (Projectile_SetSparkTile) while its state counts up.
;
; Status:  confirmed
; ---------------------------------------------------------------------------

; ---------------------------------------------------------------------------
; LinkProjectile_Spark
;
; Link's projectile x after it hit something or a beam ran out:
; a spark that keeps moving for 7 frames (objState $F2 up by 2 to 0).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
LinkProjectile_Spark:
    jsr     LinkProjectile_Move     ; $9908  keep moving
    ldy     objOamOffset+13,x       ; $990B  its sprite
    lda     objState+13,x           ; $990D  the spark's tile by state
    jsr     Projectile_SetSparkTile ; $990F
    lda     objY+13,x               ; $9912  Y
    sta     oamBuffer,y             ; $9914
    lda     objX+13,x               ; $9917  screen X
    sbc     scrollX                 ; $9919
    sta     oamBuffer+3,y           ; $991C
    inc     objState+13,x           ; $991F  2 per frame, to 0: 7 frames
    inc     objState+13,x           ; $9921
    rts                             ; $9923

; ---------------------------------------------------------------------------
; Scroll_UpdateDone
;
; Return (shared tail of Scroll_Update).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Scroll_UpdateDone:
    rts                             ; $9924

; ---------------------------------------------------------------------------
; Scroll_Update
;
; Side view: scroll the screen by Link's movement this frame (linkDeltaX),
; which keeps him at screen X $70-$71, within the area's limits
; (sramScrollMinPage, sramScrollMaxPage).  At the left limit (within 4
; pixels of it) the screen holds until Link, facing right, reaches screen X
; $70; at the right limit until Link, facing left, is back left of $71
; (scrollHeld = 1 meanwhile).  Sets scrollDir, and when the direction
; changes turns the column drawing round (columnDrawDir).  Does nothing in
; single-screen areas or while scrollFrozen is set.  Checked over the
; first 60000 frames of the 100% movie.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Scroll_Update:
    ldy     areaLastPage            ; $9925
    beq     Scroll_UpdateDone       ; $9927  one page: no scrolling
    lda     scrollFrozen            ; $9929
    bne     Scroll_UpdateDone       ; $992C  frozen (boss rooms)
    sta     scrollHeld              ; $992E  0: the screen follows Link (a = 0)
    lda     a:linkDeltaX            ; $9931  how far Link moved this frame
    sta     temp0                   ; $9934
    ldx     objFacing               ; $9936  1 right, 2 left
    lda     scrollXHi               ; $9938  at the left limit?
    cmp     sramScrollMinPage,y     ; $993B
    bmi     @atLeftLimit            ; $993E
    bne     @checkRightLimit        ; $9940
    lda     scrollX                 ; $9942  within 4 pixels of it?
    cmp     #$04                    ; $9945
    bcs     @checkRightLimit        ; $9947  no: free to scroll

@atLeftLimit:
    dex                             ; $9949  at the left limit:
    bne     @held                   ; $994A  facing left: held
    lda     drawScreenX             ; $994C  facing right: once Link is at
    clc                             ; $994E
    adc     #$20                    ; $994F  screen X $70 or more,
    cmp     #$90                    ; $9951
    bcc     @held                   ; $9953  scroll

@checkRightLimit:
    lda     scrollX                 ; $9955  at the right limit?
    clc                             ; $9958
    adc     #$02                    ; $9959
    lda     scrollXHi               ; $995B
    adc     #$00                    ; $995E
    cmp     sramScrollMaxPage,y     ; $9960  (2 pixels short of it)
    bne     @scroll                 ; $9963  no: free to scroll
    dex                             ; $9965  facing right: held
    beq     @held                   ; $9966
    lda     drawScreenX             ; $9968  facing left: while Link is left
    sec                             ; $996A
    sbc     #$20                    ; $996B
    cmp     #$51                    ; $996D  of screen X $71,
    bcc     @scroll                 ; $996F  scroll

@held:
    inc     scrollHeld              ; $9971  1: held at the end of the area
    jmp     Scroll_SetRightEdge     ; $9974

@scroll:
    ldy     temp0                   ; $9977
    tya                             ; $9979  Link didn't move: nothing to do
    beq     Scroll_SetRightEdgeDone ; $997A
    clc                             ; $997C
    adc     columnScroll            ; $997D  the column drawing keeps count
    sta     columnScroll            ; $9980
    ldx     #$01                    ; $9983  scrolling right (1),
    stx     scrollDir               ; $9985
    dex                             ; $9988  dx's high byte 0
    tya                             ; $9989
    pha                             ; $998A
    bpl     @checkDir               ; $998B
    dex                             ; $998D  or left (2): high byte $FF
    inc     scrollDir               ; $998E

@checkDir:
    stx     temp0                   ; $9991
    ldy     scrollDir               ; $9993
    cpy     columnDrawDir           ; $9996  the direction columns are drawn in?
    beq     @move                   ; $9999  same: just scroll
    lda     columnScroll            ; $999B  turned: unless a column was just
    bmi     @turn                   ; $999E
    cmp     #$20                    ; $99A0  finished (count 0-$1F),
    bcc     @move                   ; $99A2

@turn:
    sty     columnDrawDir           ; $99A4  draw toward the new side,
    lda     columnDrawStep          ; $99A7  with the edges moved past the column
    cmp     #$06                    ; $99AA  that was half drawn
    bcs     @newColumn              ; $99AC
    cmp     #$02                    ; $99AE
    bcs     @advanceOnce            ; $99B0
    jsr     Scroll_AdvanceColumn    ; $99B2

@advanceOnce:
    jsr     Scroll_AdvanceColumn    ; $99B5

@newColumn:
    lda     #$00                    ; $99B8  and a new column
    sta     columnDrawStep          ; $99BA

@move:
    pla                             ; $99BD  dx
    clc                             ; $99BE
    adc     scrollX                 ; $99BF  + scroll
    sta     scrollX                 ; $99C2
    sta     ppuScrollX              ; $99C5  the PPU's too
    lda     scrollXHi               ; $99C7
    adc     temp0                   ; $99CA
    sta     scrollXHi               ; $99CC
    and     #$01                    ; $99CF  its page's nametable
    sta     playfieldNametable      ; $99D1

; ---------------------------------------------------------------------------
; Scroll_SetRightEdge
;
; Set scrollRightX/Hi to the X position of the screen's right edge
; (scrollX + 255).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Scroll_SetRightEdge:
    lda     scrollX                 ; $99D4
    clc                             ; $99D7
    adc     #$FF                    ; $99D8  + 255
    sta     scrollRightX            ; $99DA
    lda     scrollXHi               ; $99DD
    adc     #$00                    ; $99E0
    sta     scrollRightXHi          ; $99E2

; ---------------------------------------------------------------------------
; Scroll_SetRightEdgeDone
;
; Return (shared tail of Scroll_SetRightEdge).
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Scroll_SetRightEdgeDone:
    rts                             ; $99E5

; ---------------------------------------------------------------------------
; Scroll_DrawColumns
;
; Side view, end of each frame: draw the columns of the area that scroll
; into view, a little at a time (Scroll_DrawColumnStep, 8 steps per column,
; columnDrawStep), tracking the left and right edges in columnPage and
; columnIndex.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Scroll_DrawColumns:
    lda     columnDrawStep          ; $99E6
    bne     Scroll_DrawColumnStep   ; $99E9  a column under way: its next step
    lda     columnScroll            ; $99EB  scrolled 32 pixels either way?
    bmi     @left                   ; $99EE  left
    cmp     #$20                    ; $99F0
    bcc     Scroll_SetRightEdgeDone ; $99F2  not yet
    sbc     #$20                    ; $99F4  right: count 32 off
    jmp     @newString              ; $99F6

@left:
    clc                             ; $99F9
    adc     #$20                    ; $99FA  left: count 32 back

@newString:
    sta     columnScroll            ; $99FC
    lda     #$00                    ; $99FF  a new column in ppuBuffer2
    sta     ppuBuffer2Len           ; $9A01

Scroll_DrawColumnStep:
    ; QUIRK: the clear loop at the start of a column stores attrColumn+7
    ; down to +1: it misses +0 (which Ppu_WriteAttrColumn already cleared)
    ; and clears $0478, past the array.
    dec     columnDrawStep          ; $9A04  next step (8 down to 0)
    bpl     @step                   ; $9A07
    lda     #$08                    ; $9A09  start a column: 8 steps,
    sta     columnDrawStep          ; $9A0B
    lda     #$00                    ; $9A0E
    ldx     #$07                    ; $9A10  7 down to 1: attrColumn+1 to +7

@loop:
    sta     attrColumn,x            ; $9A12
    dex                             ; $9A15
    bne     @loop                   ; $9A16

@step:
    lda     columnDrawStep          ; $9A18
    jsr     JumpTable               ; $9A1B  by step, from 8 down to 0
; (inline jump table)
    .word   Scroll_RequestAttrColumn ; $9A1E
    .word   Scroll_AdvanceColumn    ; $9A20
    .word   Scroll_QueueColumnTiles ; $9A22
    .word   Scroll_QueueColumnTiles ; $9A24
    .word   Scroll_LoadColumnTiles  ; $9A26
    .word   Scroll_AdvanceColumn    ; $9A28
    .word   Scroll_QueueColumnTiles ; $9A2A
    .word   Scroll_QueueColumnTiles ; $9A2C
    .word   Scroll_LoadColumnTiles  ; $9A2E

; ---------------------------------------------------------------------------
; Scroll_AdvanceColumn
;
; Advance columnIndex (and columnPage at the end of a page, wrapping after
; the area's last page) at the edge being drawn.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Scroll_AdvanceColumn:
    lda     columnDrawDir           ; $9A30  drawing direction:
    ldx     #$01                    ; $9A33  both edges
    lsr     a                       ; $9A35
    bcc     @leftEdge               ; $9A36  left

@loop:
    ldy     columnIndex,x           ; $9A38  right: next column
    iny                             ; $9A3B
    tya                             ; $9A3C
    and     #$0F                    ; $9A3D
    sta     columnIndex,x           ; $9A3F
    bne     @nextEdge               ; $9A42
    inc     columnPage,x            ; $9A44  next page,
    lda     columnPage,x            ; $9A47
    cmp     columnLastPage          ; $9A4A  past the last page?
    bcc     @nextEdge               ; $9A4D
    beq     @nextEdge               ; $9A4F
    lda     #$00                    ; $9A51  wrap to page 0
    sta     columnPage,x            ; $9A53

@nextEdge:
    dex                             ; $9A56  the other edge
    bpl     @loop                   ; $9A57
    rts                             ; $9A59

@leftEdge:
    ldy     columnIndex,x           ; $9A5A  left: previous column
    dey                             ; $9A5D
    tya                             ; $9A5E
    and     #$0F                    ; $9A5F
    sta     columnIndex,x           ; $9A61
    cmp     #$0F                    ; $9A64
    bne     @nextLeftEdge           ; $9A66
    dec     columnPage,x            ; $9A68  previous page,
    bpl     @nextLeftEdge           ; $9A6B
    lda     columnLastPage          ; $9A6D  wrap to the last page
    sta     columnPage,x            ; $9A70

@nextLeftEdge:
    dex                             ; $9A73
    bpl     @leftEdge               ; $9A74
    rts                             ; $9A76

; ---------------------------------------------------------------------------
; Scroll_LoadColumnTiles
;
; Copy the 13 area tiles of the column being drawn into columnTiles.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Scroll_LoadColumnTiles:
    lda     columnDrawDir           ; $9A77  drawing direction:
    lsr     a                       ; $9A7A  carry = 1 right
    ldx     columnIndex             ; $9A7B  left edge's column
    lda     columnPage              ; $9A7E
    bcc     @load                   ; $9A81
    ldx     columnIndex+1           ; $9A83  right edge's
    lda     columnPage+1            ; $9A86

@load:
    jsr     AreaMap_GetPagePtr_Bank0 ; $9A89  its page
    txa                             ; $9A8C
    tay                             ; $9A8D
    ldx     #$00                    ; $9A8E  13 rows:

@loop:
    lda     (temp14),y              ; $9A90
    sta     columnTiles,x           ; $9A92
    tya                             ; $9A95
    clc                             ; $9A96
    adc     #$10                    ; $9A97  next row
    tay                             ; $9A99
    inx                             ; $9A9A
    cpx     #$0D                    ; $9A9B
    bne     @loop                   ; $9A9D
    rts                             ; $9A9F

AreaPagePtrsLo_Bank0:
