    beq     @next                   ; $9B37
    tya                             ; $9B39  its sprite: 1 + item
    asl     a                       ; $9B3A
    asl     a                       ; $9B3B
    pha                             ; $9B3C
    tax                             ; $9B3D
    lda     #$B7                    ; $9B3E  Y $B7
    sta     oamBuffer+4,x           ; $9B40
    tya                             ; $9B43  tile $8C + item x 2
    asl     a                       ; $9B44
    adc     #$8C                    ; $9B45
    sta     oamBuffer+5,x           ; $9B47
    lda     #$01                    ; $9B4A  palette 1
    sta     oamBuffer+6,x           ; $9B4C
    pla                             ; $9B4F  X: first + item x 8
    asl     a                       ; $9B50
    adc     temp1                   ; $9B51
