    asl     a                       ; $A64A
    tay                             ; $A64B
    lda     LevelUpRowPtrs,y        ; $A64C
    sta     temp2                   ; $A64F
    lda     LevelUpRowPtrs+1,y      ; $A651
    sta     temp3                   ; $A654
    lda     LevelUpRowPtrs2,y       ; $A656
    sta     temp4                   ; $A659
    lda     LevelUpRowPtrs2+1,y     ; $A65B
    sta     temp5                   ; $A65E
    ldy     #$0D                    ; $A660  14 tiles

@loop:
    lda     (temp2),y               ; $A662
    sta     menuRowTiles,y          ; $A664
    lda     (temp4),y               ; $A667
    sta     menuRowTiles2,y         ; $A669
    dey                             ; $A66C
    bpl     @loop                   ; $A66D
    ldx     levelUpCursor           ; $A66F  the cursor's row?
    lda     LevelUpCursorRows,x     ; $A672
    cmp     menuRow                 ; $A675
    bne     @done                   ; $A678
    txa                             ; $A67A
    ldx     #$FB                    ; $A67B  the arrow
