    .byte   $09                                                             ; $A68A

; ---------------------------------------------------------------------------
; LevelUp_ApplyChoice
;
; Level up window step 6: redraw the chosen stat's level bar row, now one
; tile longer (nothing for Cancel), set the blink timer (menuRepeatTimer),
