; ---------------------------------------------------------------------------
; Saria_BuildBridge
;
; The bridge in Saria (World_GetIndex 1, town 2, area 6): when Link is on
; its third page and techniques bit 0 is set, pause the game
; (pauseState 1) and extend the bridge a tile every 8 frames (bridgeStep,
; BridgeTileString), with a sound; after 16 steps write the bridge into
; the area tile map and clear techniques bit 0.
;
; Status:  confirmed
; ---------------------------------------------------------------------------
Saria_BuildBridge:
    ldy     #$F0                    ; $A7AB  a delay, past the vertical blank

@loop:
    nop                             ; $A7AD
    dey                             ; $A7AE
    bne     @loop                   ; $A7AF

@loop2:
    bit     PPUSTATUS               ; $A7B1  split the screen under the status bar
    bvc     @loop2                  ; $A7B4
    lda     ppuCtrlShadow           ; $A7B6
    ora     playfieldNametable      ; $A7B8
    sta     ppuCtrlShadow           ; $A7BB
    ldx     ppuScrollX              ; $A7BD
    ldy     #$10                    ; $A7BF

@loop3:
    dey                             ; $A7C1
    bne     @loop3                  ; $A7C2
    sta     PPUCTRL                 ; $A7C4
    stx     PPUSCROLL               ; $A7C7
    sty     PPUSCROLL               ; $A7CA
    inc     a:frameCounter          ; $A7CD  time goes on while paused
    lda     a:frameCounter          ; $A7D0
    and     #$07                    ; $A7D3  every 8 frames:
    bne     @done                   ; $A7D5
    ldy     #$09                    ; $A7D7  a bridge tile pair (PPU $272F) and its attributes

@loop4:
    lda     BridgeTileString,y      ; $A7D9
    sta     ppuBuffer0,y            ; $A7DC
    dey                             ; $A7DF
    bpl     @loop4                  ; $A7E0
    lda     ppuBuffer0+1            ; $A7E2  one tile further left per step
    sec                             ; $A7E5
    sbc     bridgeStep              ; $A7E6
    sta     ppuBuffer0+1            ; $A7E9
    lda     #$02                    ; $A7EC  the bridge sound
    sta     sfxRequest+1            ; $A7EE
    inc     bridgeStep              ; $A7F0
    lda     bridgeStep              ; $A7F3
    and     #$0F                    ; $A7F6  16 tiles?
    bne     @done                   ; $A7F8
    sta     bridgeStep              ; $A7FA  yes: from step 0
    lda     #$10                    ; $A7FD  the bridge into the tile map ($6310):
    sta     temp0                   ; $A7FF
    lda     #$63                    ; $A801
    sta     temp1                   ; $A803
    ldx     #$51                    ; $A805  tile $51 on the upper row,

@loop5:
    ldy     #$07                    ; $A807  8 metatiles

@loop6:
    txa                             ; $A809
    sta     (temp0),y               ; $A80A
    dey                             ; $A80C
    bpl     @loop6                  ; $A80D
    ldx     #$56                    ; $A80F  $56 on the lower
    lda     temp0                   ; $A811
    clc                             ; $A813
    adc     #$10                    ; $A814
    sta     temp0                   ; $A816
    cmp     #$30                    ; $A818  two rows
    bne     @loop5                  ; $A81A
    lda     #$00                    ; $A81C  unpause
    sta     pauseState              ; $A81E
    lda     techniques              ; $A821  the bridge is built
    and     #$FE                    ; $A824
    sta     techniques              ; $A826

@done:
    rts                             ; $A829

